--
-- Estrutura para tabela `gestao_diagnostico_perguntas`
--

CREATE TABLE `gestao_diagnostico_perguntas` (
  `id` int(11) NOT NULL,
  `secao` varchar(50) NOT NULL,
  `texto_pergunta` varchar(255) NOT NULL,
  `tipo` varchar(50) DEFAULT 'escala',
  `opcoes` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`opcoes`)),
  `logica_ia` text DEFAULT NULL,
  `texto_min` varchar(100) NOT NULL COMMENT 'Label para nota 0',
  `texto_max` varchar(100) NOT NULL COMMENT 'Label para nota 100',
  `ordem` int(11) DEFAULT 0,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

--
-- Despejando dados para a tabela `gestao_diagnostico_perguntas`
--

INSERT INTO `gestao_diagnostico_perguntas` (`id`, `secao`, `texto_pergunta`, `tipo`, `opcoes`, `logica_ia`, `texto_min`, `texto_max`, `ordem`, `created_at`) VALUES
(1, 'perfil', 'Qual é o faturamento médio mensal da clínica (considerando os últimos 6 meses)?', 'selecao', '[\"Até R$ 30k (Consultório Inicial)\",\"De R$ 30k a R$ 100k (Pequena Clínica)\",\"De R$ 100k a R$ 300k (Clínica em Crescimento)\",\"De R$ 300k a R$ 1M (Clínica Consolidada)\",\"Acima de R$ 1M (Grande Porte\\/Rede)\"]', 'Define o orçamento disponível e complexidade das tarefas.', '', '', 1, '2025-12-27 08:48:26'),
(2, 'perfil', 'Quantos profissionais de saúde (Médicos, Dentistas, Terapeutas) atendem na clínica hoje?', 'selecao', '[\"Apenas eu (Eupresa)\",\"2 a 5 profissionais\",\"6 a 15 profissionais\",\"Mais de 15 profissionais\"]', 'Define foco em produtividade individual vs cultura/processos.', '', '', 2, '2025-12-27 08:48:26'),
(3, 'perfil', 'Quantos colaboradores de suporte (recepção, limpeza, financeiro, gestão) a clínica possui?', 'numero', NULL, 'Cálculo de eficiência Staff/Médico.', '', '', 3, '2025-12-27 08:48:26'),
(4, 'modelo', 'Qual a porcentagem do seu faturamento que vem de planos de saúde/convênios?', 'selecao', '[\"0% (100% Particular)\",\"Até 30% (Híbrido - Foco Particular)\",\"De 30% a 70% (Híbrido Equilibrado)\",\"Acima de 70% (Foco em Volume\\/Convênio)\"]', 'Foco em Eficiência (Convênio) vs Experiência/Branding (Particular).', '', '', 4, '2025-12-27 08:48:26'),
(5, 'modelo', 'Como você define o posicionamento de preço/marca da sua clínica hoje frente aos concorrentes?', 'escala', '[\"Popular \\/ Acessível\",\"Médio Mercado\",\"Premium \\/ Alto Padrão\"]', 'Evita sugestões contraditórias de preço.', '', '', 5, '2025-12-27 08:48:26'),
(6, 'modelo', 'A clínica atua com uma única especialidade ou é multidisciplinar?', 'selecao', '[\"Mono-especialidade\",\"Multidisciplinar \\/ Policlínica\"]', 'Cross-selling (Multi) vs Autoridade de Nicho (Mono).', '', '', 6, '2025-12-27 08:48:26'),
(7, 'financeiro', 'Existe uma separação rigorosa entre as contas bancárias da clínica e as contas pessoais dos sócios?', 'selecao', '[\"Não, pagamos contas pessoais na conta da clínica\",\"Parcialmente, às vezes misturamos\",\"Sim, totalmente separadas\"]', 'Se misturar: Bloqueio de Estratégia. OKR 1 virou Profissionalização Financeira.', '', '', 7, '2025-12-27 08:48:26'),
(8, 'financeiro', 'Como o controle financeiro (entradas e saídas) é feito hoje?', 'selecao', '[\"Não fazemos controle formal\",\"Planilhas manuais\",\"Sistema de Gestão (ERP)\",\"BPO Financeiro\"]', 'Implantação de Controle Básico vs Análise Avançada.', '', '', 8, '2025-12-27 08:48:26'),
(9, 'financeiro', 'Você analisa um Demonstrativo de Resultados (DRE) mensalmente?', 'selecao', '[\"Não sei o que é \\/ Nunca analiso\",\"Analiso apenas saldo bancário\",\"Sim, analiso DRE detalhado\"]', 'Identifica Miopia Financeira.', '', '', 9, '2025-12-27 08:48:26'),
(10, 'financeiro', 'Qual a média da sua Margem de Lucro Líquida nos últimos meses?', 'selecao', '[\"Negativa (Prejuízo)\",\"Zero \\/ Empata\",\"Baixa (1% a 10%)\",\"Saudável (10% a 20%)\",\"Alta (Acima de 20%)\",\"Não sei dizer\"]', 'Modo Sobrevivência vs Modo Investimento.', '', '', 10, '2025-12-27 08:48:26'),
(11, 'financeiro', 'Como você define o preço das suas consultas e procedimentos?', 'selecao', '[\"Baseado na concorrência\",\"Chute \\/ Intuição\",\"Tabela dos convênios\",\"Cálculo técnico (Custos + Margem)\"]', 'Risco de prejuízo invisível se for chute/concorrência.', '', '', 11, '2025-12-27 08:48:26'),
(12, 'financeiro', 'Você oferece parcelamento próprio? Como é a inadimplência?', 'selecao', '[\"Não ofereço (Risco Zero)\",\"Baixa (Irrelevante)\",\"Alta (Muitos atrasados)\"]', 'Recuperação de Crédito se alta.', '', '', 12, '2025-12-27 08:48:26'),
(13, 'operacional', 'Em média, qual porcentagem da agenda disponível dos profissionais é preenchida mensalmente?', 'selecao', '[\"Abaixo de 50% (Muita ociosidade)\",\"De 50% a 80% (Ocupação média)\",\"Acima de 80% (Agenda cheia)\",\"Acima de 100% (Lista de espera)\"]', 'Alerta Vermelho de Vendas vs Alerta de Expansão.', '', '', 13, '2025-12-27 08:48:26'),
(14, 'operacional', 'Qual a estimativa de pacientes que agendam mas faltam sem avisar (No-Show)?', 'selecao', '[\"Baixíssima (Menos de 5%)\",\"Aceitável (5% a 15%)\",\"Preocupante (15% a 30%)\",\"Crítica (Mais de 30%)\"]', 'Prioridade 1: Blindagem de Agenda se alta.', '', '', 14, '2025-12-27 08:48:26'),
(15, 'operacional', 'Como é feita a confirmação dos agendamentos hoje?', 'selecao', '[\"Não confirmamos\",\"Manual (Secretária liga\\/zap)\",\"Automática (Software)\"]', 'Gargalo na recepção se manual.', '', '', 15, '2025-12-27 08:48:26'),
(16, 'operacional', 'Quanto tempo, em média, o paciente aguarda na recepção além do horário marcado?', 'selecao', '[\"Quase nada (Pontual)\",\"Até 20 minutos\",\"20 a 40 minutos\",\"Mais de 40 minutos\"]', 'Impacta NPS. Sugerir ajuste de intervalo.', '', '', 16, '2025-12-27 08:48:26'),
(17, 'operacional', 'Por onde chegam os agendamentos? (Pode marcar vários)', 'multipla', '[\"Telefone fixo\",\"WhatsApp da Recepção\",\"WhatsApp Pessoal do Médico\",\"Agendamento Online\",\"Direct Instagram\"]', 'Risco de perder leads se disperso. Profissionalização se usar pessoal.', '', '', 17, '2025-12-27 08:48:26'),
(18, 'operacional', 'Como são registrados os dados clínicos (histórico) dos pacientes?', 'selecao', '[\"Papel \\/ Fichas físicas\",\"Prontuário Eletrônico\",\"Misto\"]', 'Digitalização é pré-requisito para CRM.', '', '', 18, '2025-12-27 08:48:26'),
(19, 'aquisicao', 'Qual a principal fonte de novos pacientes hoje?', 'selecao', '[\"Indicação (Boca a boca)\",\"Redes Sociais Orgânicas\",\"Tráfego Pago\",\"Convênios\",\"Passantes\"]', 'Dependência de canais vs Diversificação.', '', '', 19, '2025-12-27 08:48:26'),
(20, 'aquisicao', 'Existe uma verba mensal fixa destinada a marketing/anúncios?', 'selecao', '[\"Não investimos nada\",\"Sim, mas é esporádico\",\"Sim, temos um budget fixo mensal\"]', 'Definir orçamento de testes se Não.', '', '', 20, '2025-12-27 08:48:26'),
(21, 'aquisicao', 'Quando alguém entra em contato perguntando preço, o que a equipe faz?', 'selecao', '[\"Passa o preço e desliga (Informante)\",\"Passa o preço e pergunta (Reativa)\",\"Usa script de vendas (Ativa)\"]', 'Treinamento de Script se Informante.', '', '', 21, '2025-12-27 08:48:26'),
(22, 'aquisicao', 'Existe um processo para re-contactar quem pediu informações mas não agendou?', 'selecao', '[\"Não, esquecemos\",\"Sim, lista de repescagem\"]', 'Implantação de CRM Simples se Não.', '', '', 22, '2025-12-27 08:48:26'),
(23, 'jornada', 'A clínica mede a satisfação dos pacientes ativamente (NPS)?', 'selecao', '[\"Não medimos\",\"Caixinha de sugestões\",\"Sim, pesquisa digital NPS\"]', 'Automatizar NPS se Não.', '', '', 23, '2025-12-27 08:48:26'),
(24, 'jornada', 'Se um paciente reclama, qual é o procedimento padrão?', 'selecao', '[\"Não temos padrão\",\"Processo de ouvidoria registrado\"]', 'Risco de reputação se sem padrão.', '', '', 24, '2025-12-27 08:48:26'),
(25, 'jornada', 'A clínica entra em contato proativamente com pacientes sumidos (Recall)?', 'selecao', '[\"Não, esperamos ele ligar\",\"Sim, esporadicamente\",\"Sim, recorrente\"]', 'Régua de Relacionamento se Não.', '', '', 25, '2025-12-27 08:48:26'),
(26, 'equipe', 'Com que frequência você precisa contratar novos funcionários (Turnover)?', 'selecao', '[\"Raramente (+2 anos)\",\"Às vezes (1x ano)\",\"Frequentemente\"]', 'Estruturação de RH se Frequente.', '', '', 26, '2025-12-27 08:48:26'),
(27, 'equipe', 'Existem reuniões de alinhamento com a equipe?', 'selecao', '[\"Nunca\",\"Esporadicamente\",\"Sim, semanais\\/mensais\"]', 'Reunião Semanal se Nunca.', '', '', 27, '2025-12-27 08:48:26'),
(28, 'equipe', 'A equipe de recepção ganha algum variável por desempenho?', 'selecao', '[\"Não, apenas fixo\",\"Sim, comissão\\/metas\"]', 'Política de comissão se Fixo.', '', '', 28, '2025-12-27 08:48:26'),
(29, 'momento', 'Qual o papel atual dos sócios/donos na rotina da clínica?', 'selecao', '[\"100% Assistencial (Atendem o dia todo)\",\"Híbrido (Meio a meio)\",\"100% Gestão\",\"Investidor\"]', 'Prioridade Crítica: Estruturação de Tempo se for 100% Assistencial.', '', '', 50, '2025-12-27 08:48:26'),
(30, 'momento', 'Qual é o objetivo nº 1 da clínica para os próximos 6 meses?', 'selecao', '[\"Sobrevivência \\/ Organização\",\"Aumentar Faturamento\",\"Aumentar Lucratividade\",\"Expansão\"]', 'Define o Tema Central (North Star Metric) do projeto.', '', '', 51, '2025-12-27 08:48:26');

