--
-- Estrutura para tabela `gestao_diagnostico_resultados`
--

CREATE TABLE `gestao_diagnostico_resultados` (
  `id` int(11) NOT NULL,
  `user_id` int(11) NOT NULL,
  `data_realizacao` datetime DEFAULT current_timestamp(),
  `score_geral` decimal(5,2) DEFAULT NULL,
  `score_operacao` decimal(5,2) DEFAULT NULL,
  `score_financeiro` decimal(5,2) DEFAULT NULL,
  `score_aquisicao` int(11) DEFAULT 0,
  `nivel_maturidade` varchar(50) DEFAULT NULL,
  `analise_ia` text DEFAULT NULL,
  `score_equipe` int(11) DEFAULT 0,
  `score_jornada` int(11) DEFAULT 0,
  `sugestao_projetos` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`sugestao_projetos`))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

--
-- Despejando dados para a tabela `gestao_diagnostico_resultados`
--

INSERT INTO `gestao_diagnostico_resultados` (`id`, `user_id`, `data_realizacao`, `score_geral`, `score_operacao`, `score_financeiro`, `score_aquisicao`, `nivel_maturidade`, `analise_ia`, `score_equipe`, `score_jornada`, `sugestao_projetos`) VALUES
(42, 1, '2025-12-27 05:48:30', 0.00, NULL, NULL, NULL, 'Em Análise', '{\"scores\":{\"operacional\":45,\"financeiro\":50,\"aquisicao\":35,\"equipe\":40},\"analise_executiva\":\"<p><strong>A área operacional enfrenta grandes desafios relacionados à falta de processos estruturados e automação insuficiente, o que impacta diretamente na eficiência e qualidade dos serviços entregues. A ausência de fluxos documentados e sistemas integrados ainda mantém muitas atividades em modo manual, gerando retrabalho e atrasos.</strong></p><p><strong>No âmbito financeiro e de aquisição, a situação não melhora significativamente, com controles básicos fragmentados e estratégias de aquisição pouco efetivas. A equipe carece de desenvolvimento e gestão adequados, comprometendo o desempenho geral da organização e limitando a capacidade de crescimento sustentável.</strong></p>\",\"projetos\":[{\"titulo\":\"Automatização de Processos Operacionais\",\"descricao\":\"Automatizar e padronizar os processos operacionais para aumentar eficiência, reduzir erros e agilizar entregas, melhorando a qualidade do serviço e a satisfação do cliente.\",\"prioridade\":\"alta\",\"okrs\":[{\"titulo\":\"Alcançar processos operacionais padronizados e semi-automatizados\",\"krs\":[\"Documentar 100% dos principais processos operacionais até 2024-08-31\",\"Implementar sistema de automação para 70% das tarefas repetitivas até 2024-10-31\"]}],\"tarefas\":[{\"titulo\":\"Mapear processos operacionais críticos\",\"descricao\":\"**O que é:** Identificar e documentar os processos mais relevantes.\\n\\n**Passo a Passo:**\\n1. Reunir equipe operacional para levantamento dos processos.\\n2. Documentar fluxos em formato padrão.\\n\\n**Resultado Esperado:** Processos críticos mapeados e disponíveis para análise.\",\"prazo\":\"2024-07-15\"},{\"titulo\":\"Selecionar ferramenta de automação adequada\",\"descricao\":\"**O que é:** Escolher software que suporte automação dos processos mapeados.\\n\\n**Passo a Passo:**\\n1. Levantar opções no mercado.\\n2. Avaliar custo-benefício e compatibilidade.\\n3. Apresentar recomendação à diretoria.\\n\\n**Resultado Esperado:** Ferramenta definida para implementação.\",\"prazo\":\"2024-07-31\"},{\"titulo\":\"Treinar equipe para utilização da ferramenta\",\"descricao\":\"**O que é:** Capacitar colaboradores para operar a nova plataforma.\\n\\n**Passo a Passo:**\\n1. Agendar treinamentos presenciais e online.\\n2. Desenvolver material de apoio.\\n3. Realizar sessões práticas.\\n\\n**Resultado Esperado:** Equipe habilitada para uso eficiente da ferramenta.\",\"prazo\":\"2024-08-15\"},{\"titulo\":\"Implementar automação nos processos prioritários\",\"descricao\":\"**O que é:** Configurar e rodar automação para principais tarefas mapeadas.\\n\\n**Passo a Passo:**\\n1. Ajustar configurações da ferramenta.\\n2. Executar testes-piloto.\\n3. Validar resultados com equipe.\\n\\n**Resultado Esperado:** Processos automáticos funcionando e monitorados.\",\"prazo\":\"2024-09-30\"},{\"titulo\":\"Monitorar e otimizar processos automatizados\",\"descricao\":\"**O que é:** Avaliar desempenho contínuo e promover melhorias.\\n\\n**Passo a Passo:**\\n1. Definir indicadores de eficiência.\\n2. Coletar dados de uso semanalmente.\\n3. Ajustar processos quando necessário.\\n\\n**Resultado Esperado:** Processos otimizados e controlados por KPIs.\",\"prazo\":\"2024-10-31\"}]},{\"titulo\":\"Reestruturação Financeira e Controle de Aquisição\",\"descricao\":\"Melhorar o controle financeiro e os processos de aquisição para reduzir custos, evitar desperdícios e garantir melhor planejamento orçamentário, aumentando a sustentabilidade do negócio.\",\"prioridade\":\"media\",\"okrs\":[{\"titulo\":\"Estabelecer controle financeiro e processos de aquisição eficientes\",\"krs\":[\"Implantar sistema de controle financeiro integrado até 2024-09-30\",\"Padronizar o processo de aquisição com 80% dos fornecedores cadastrados e aprovados até 2024-11-30\"]}],\"tarefas\":[{\"titulo\":\"Diagnosticar atuais processos financeiros e de aquisição\",\"descricao\":\"**O que é:** Levantar práticas, falhas e oportunidades existentes.\\n\\n**Passo a Passo:**\\n1. Entrevistar gestores financeiros e responsáveis por compras.\\n2. Revisar documentação e contratos.\\n\\n**Resultado Esperado:** Relatório de diagnóstico completo.\",\"prazo\":\"2024-07-20\"},{\"titulo\":\"Definir critérios para seleção e avaliação de fornecedores\",\"descricao\":\"**O que é:** Criar parâmetros para compras eficientes e seguras.\\n\\n**Passo a Passo:**\\n1. Analisar necessidades internas.\\n2. Definir indicadores de desempenho e compliance.\\n3. Formalizar critérios em documento.\\n\\n**Resultado Esperado:** Critérios claros para avaliação de fornecedores.\",\"prazo\":\"2024-08-10\"},{\"titulo\":\"Implementar sistema integrado de controle financeiro\",\"descricao\":\"**O que é:** Adotar plataforma que centralize e automatize finanças e aquisições.\\n\\n**Passo a Passo:**\\n1. Selecionar sistema conforme necessidade.\\n2. Configurar base de dados e integrações.\\n3. Treinar equipe para uso.\\n\\n**Resultado Esperado:** Sistema implantado e funcional.\",\"prazo\":\"2024-09-30\"},{\"titulo\":\"Cadastrar e qualificar fornecedores\",\"descricao\":\"**O que é:** Formalizar cadastro para uso transparente e seguro nas compras.\\n\\n**Passo a Passo:**\\n1. Solicitar informações e documentação dos fornecedores atuais.\\n2. Avaliar conforme critérios estabelecidos.\\n3. Atualizar banco de dados.\\n\\n**Resultado Esperado:** Base de fornecedores qualificada e atualizada.\",\"prazo\":\"2024-10-31\"},{\"titulo\":\"Monitorar indicadores financeiros e de aquisição\",\"descricao\":\"**O que é:** Estabelecer acompanhamento e ajustes constantes.\\n\\n**Passo a Passo:**\\n1. Definir KPIs financeiros e indicadores de compra.\\n2. Realizar reuniões mensais de análise.\\n3. Implementar melhorias conforme resultado.\\n\\n**Resultado Esperado:** Controle efetivo e contínuo das finanças e aquisições.\",\"prazo\":\"2024-11-30\"}]},{\"titulo\":\"Desenvolvimento e Gestão de Equipe\",\"descricao\":\"Estruturar práticas de gestão de pessoas e capacitar a equipe para aumentar engajamento, produtividade e retenção de talentos, alinhando a equipe aos objetivos estratégicos da empresa.\",\"prioridade\":\"media\",\"okrs\":[{\"titulo\":\"Fortalecer a gestão de pessoas e capacitação interna\",\"krs\":[\"Implementar programa de treinamento e desenvolvimento com participação de 80% da equipe até 2024-10-31\",\"Estabelecer avaliações de desempenho trimestrais para 100% dos colaboradores até 2024-12-31\"]}],\"tarefas\":[{\"titulo\":\"Realizar diagnóstico de competências e necessidades da equipe\",\"descricao\":\"**O que é:** Identificar gaps de habilidades e áreas de melhoria.\\n\\n**Passo a Passo:**\\n1. Aplicar levantamento de competências atuais.\\n2. Analisar necessidades estratégicas.\\n\\n**Resultado Esperado:** Mapa de competências e gaps para plano de ação.\",\"prazo\":\"2024-07-25\"},{\"titulo\":\"Desenvolver programa de capacitação contínua\",\"descricao\":\"**O que é:** Estruturar treinamentos que aumentem o conhecimento técnico e comportamental.\\n\\n**Passo a Passo:**\\n1. Selecionar temas prioritários.\\n2. Planejar agenda e formato dos treinamentos.\\n3. Preparar materiais e instrutores.\\n\\n**Resultado Esperado:** Programa estruturado e divulgado para equipe.\",\"prazo\":\"2024-08-20\"},{\"titulo\":\"Implementar sistema de avaliação de desempenho\",\"descricao\":\"**O que é:** Criar processo formal para feedback e desenvolvimento.\\n\\n**Passo a Passo:**\\n1. Definir critérios e métricas de avaliação.\\n2. Comunicar processo para equipe.\\n3. Realizar avaliações piloto.\\n\\n**Resultado Esperado:** Processo de avaliação funcional e aceito.\",\"prazo\":\"2024-09-30\"},{\"titulo\":\"Promover sessões de feedback e coaching\",\"descricao\":\"**O que é:** Estimular melhoria contínua e engajamento.\\n\\n**Passo a Passo:**\\n1. Agendar reuniões individuais.\\n2. Treinar líderes em técnicas de feedback.\\n3. Documentar e acompanhar evolução.\\n\\n**Resultado Esperado:** Maior engajamento e desenvolvimento individual.\",\"prazo\":\"2024-10-31\"},{\"titulo\":\"Monitorar indicadores de engajamento e turnover\",\"descricao\":\"**O que é:** Avaliar resultados e ajustar ações.\\n\\n**Passo a Passo:**\\n1. Definir métricas e métodos de pesquisa.\\n2. Aplicar pesquisas periódicas.\\n3. Analisar resultados e sugerir melhorias.\\n\\n**Resultado Esperado:** Redução de turnover e maior satisfação.\",\"prazo\":\"2024-12-31\"}]}]}', 0, 0, NULL),
(43, 1, '2025-12-27 05:59:40', 0.00, 45.00, 50.00, 35, 'Em Análise', '<p><strong>A empresa apresenta maturidade operacional e financeira no nível básico, com processos ainda predominantemente manuais e falta de automação, o que impacta na eficiência e acuracidade das operações. A área de aquisição demonstra o maior gap, evidenciando falhas significativas na captura e conversão de leads, comprometendo o crescimento sustentável do negócio.</strong></p><p><strong>Além disso, a equipe sofre com ausência de capacitação estruturada e falta de alinhamento estratégico, agravando a baixa performance geral. É primordial implementar projetos que priorizem a digitalização dos processos e treinamento, visando rápida melhoria dos indicadores e criação de bases sólidas para escalabilidade.</strong></p>', 40, 0, NULL),
(44, 1, '2025-12-27 05:59:40', 0.00, 45.00, 50.00, 35, 'Em Análise', '<p><strong>A operação da empresa apresenta processos principalmente manuais e com baixa integração entre sistemas, o que eleva o risco de erros e retrabalho. Os controles financeiros são básicos, com falta de automação e planejamento estruturado, o que impacta diretamente na gestão do fluxo de caixa e na tomada de decisão estratégica. A área de aquisição de clientes é a mais fragilizada, destacado pelas ausências de métricas sólidas e canais pouco explorados, comprometendo o crescimento e a geração de receita.</strong></p><p><strong>Além disso, a equipe carece de estruturação em desenvolvimento e capacitação, refletindo em baixa produtividade e engajamento. Para o crescimento sustentável, é imprescindível que a empresa invista na automação dos processos, elaboração de controles financeiros mais robustos, além de fortalecer as estratégias de captação e a capacitação da equipe, combatendo as lacunas identificadas e elevando a maturidade geral.</strong></p>', 40, 0, NULL),
(45, 1, '2025-12-27 06:21:12', 46.00, 45.00, 55.00, 35, 'Em Análise', '<p><strong>A empresa apresenta processos operacionais e financeiros ainda muito dependentes de controles manuais e rotinas pouco padronizadas, aumentando os riscos de erros e retrabalhos. A baixa maturidade na área de aquisição reforça que a captação e conversão de clientes carecem de estratégias estruturadas e acompanhamento analítico mais rigoroso. </strong></p><p><strong>Do ponto de vista das equipes, há um esforço inicial na organização, porém falta mais investimento em desenvolvimento e comunicação interna para alinhar os objetivos e aumentar a produtividade. Sem uma atuação coordenada entre operações, finanças, aquisição e equipe, a empresa permanecerá com baixa eficiência e dificuldade em escalar resultados.</strong></p>', 50, 0, NULL),
(46, 1, '2025-12-27 06:27:47', 45.00, 45.00, 50.00, 35, 'Em Análise', '<h3>🔍 O Cenário Atual</h3> <p>A empresa apresenta uma maturidade operacional e financeira no estágio básico, com processos ainda manuais e pouco integrados que comprometem a eficiência e a precisão das informações. A aquisição de clientes está fragilizada, demonstrando baixa performance e falta de estratégias claras e estruturadas. A jornada do cliente carece de monitoramento ativo, o que dificulta o engajamento e a retenção.</p> <h3>⚠️ Principais Gargalos</h3> <ul><li>Processos operacionais dependentes de controles manuais e falhas de comunicação interna.</li><li>Gestão financeira sem ferramentas de acompanhamento integrado e com baixa previsibilidade.</li><li>Baixa eficácia em aquisição devido a ausência de canais diversificados e análise de dados limitada.</li><li>Falta de mapeamento e acompanhamento da jornada do cliente, prejudicando o relacionamento e oportunidade de melhoria.</li><li>Equipe com comunicação e alinhamento intermediário, necessitando de treinamentos e definição clara de responsabilidades.</li></ul> <h3>🚀 O Caminho de Ouro</h3> <p>A modernização dos processos operacionais e financeiros por meio da automação e da integração dos sistemas é fundamental para garantir maior eficiência e controle. Aliado a isso, desenvolver uma estratégia de aquisição focada em análise de dados e diversificação de canais aumentará a captação qualificada de clientes. Por fim, implementar o mapeamento da jornada do cliente e investir em capacitação da equipe elevará a experiência do cliente e o desempenho da equipe, promovendo crescimento sustentável.</p>', 55, 40, NULL),
(47, 1, '2025-12-27 06:35:39', 50.00, 55.00, 50.00, 45, 'Em Análise', '<h3>🔍 O Cenário Atual</h3> <p>A empresa apresenta um nível intermediário em suas operações e processos financeiros, com forte dependência de sistemas manuais e pouca automação. A aquisição de clientes e a jornada do consumidor estão abaixo do esperado, indicativo de falhas na captação e retenção. A equipe demonstra potencial, mas ainda carece de alinhamento e capacitação para atuar com eficiência nas áreas críticas.</p> <h3>⚠️ Principais Gargalos</h3> <ul><li>Falhas no processo de aquisição, com baixa geração e qualificação de leads.</li><li>Gestão financeira precária, dificultando o controle de custos e fluxo de caixa.</li><li>Processos operacionais pouco estruturados, gerando retrabalho e baixa produtividade.</li><li>Jornada do cliente desalinhada, com fraca experiência e altos índices de abandono.</li><li>Falta de integração e comunicação efetiva dentro da equipe.</li></ul> <h3>🚀 O Caminho de Ouro</h3> <p>Estruturar processos integrados e automatizados será chave para escalar o negócio com qualidade e segurança financeira. Investir na construção de uma jornada de cliente otimizada, aliada à capacitação do time e à implantação de métricas claras, permitirá melhorar a eficiência operacional e aumentar a aquisição e retenção. Projetos estratégicos focados em tecnologia, cultura organizacional e experiência do cliente formarão a base para um crescimento sustentável e competitivo.</p>', 60, 40, '0'),
(48, 1, '2025-12-27 06:37:53', 50.00, 55.00, 45.00, 40, 'Em Análise', '<h3>🔍 O Cenário Atual</h3> <p>A empresa apresenta processos operacionais parcialmente documentados e uma gestão financeira que ainda depende de controles manuais, o que impacta na eficiência e previsibilidade dos resultados. A equipe possui competências básicas, mas carece de estruturação e alinhamento claros para as metas. A jornada do cliente ainda é intermitente, sem integração fluida entre etapas, e a aquisição de novos clientes está baixa, com estratégias pouco definidas e escassa automação.</p> <h3>⚠️ Principais Gargalos</h3> <ul><li>Falta de automação e padronização nos processos operacionais, gerando retrabalho e ineficiência.</li><li>Controle financeiro manual e pouco estruturado, dificultando análise rápida e tomada de decisão.</li><li>Estratégias de aquisição fragmentadas e sem métricas consolidadas para avaliação de resultados.</li><li>Jornada do cliente desarticulada, impactando a experiência e retenção.</li><li>Equipe sem clareza de papéis e desenvolvimento limitado, prejudicando a execução das ações estratégicas.</li></ul> <h3>🚀 O Caminho de Ouro</h3> <p>A grande oportunidade está na implementação de soluções que integrem processos, financeiro e aquisição por meio da automação e análise de dados, potencializando a captura de clientes e a satisfação geral. O alinhamento da equipe com metas claras e a profissionalização da jornada permitirão ganhos significativos em eficiência e escalabilidade. Investir em tecnologia e capacitação são passos essenciais para transformar os gargalos em diferenciais competitivos.</p>', 50, 60, '0'),
(49, 1, '2025-12-27 06:40:29', 50.00, 55.00, 45.00, 40, 'Em Análise', '<h3>🔍 O Cenário Atual</h3><p>A empresa apresenta um nível intermediário em seus processos operacionais e financeiros, com ferramentas parcialmente automatizadas mas ainda dependentes de muitas rotinas manuais. A aquisição de clientes está fragilizada, prejudicando o crescimento sustentável, enquanto a jornada do cliente e o engajamento da equipe ainda carecem de melhorias estruturadas para garantir consistência e qualidade.</p><h3>⚠️ Principais Gargalos</h3><ul><li>Falta de automação em processos-chave operacionais, aumentando o tempo e os erros na entrega.</li><li>Controle financeiro básico, com baixa integração de dados e pouco uso de indicadores para tomada de decisão.</li><li>Estratégias de aquisição pouco estruturadas, com campanhas pouco segmentadas e baixa captação orgânica.</li><li>Jornada do cliente desarticulada, com falhas na personalização e acompanhamento pós-venda.</li><li>Comunicação interna e alinhamento da equipe insuficientes, causando retrabalhos e baixa motivação.</li></ul><h3>🚀 O Caminho de Ouro</h3><p>A oportunidade está em implementar automação progressiva e integração de sistemas para otimizar custos e tempo, aliada a um aprofundamento na segmentação e personalização da aquisição e jornada do cliente. Além disso, fortalecer a cultura organizacional com comunicação eficaz e desenvolvimento da equipe irá sustentar o crescimento e elevar o desempenho em todas as áreas.</p>', 60, 50, '[{\"titulo\":\"Automatização Operacional Integrada\",\"descricao\":\"Automatizar processos críticos para aumentar eficiência, reduzir erros e liberar a equipe para atividades estratégicas.\",\"prioridade\":\"alta\",\"okrs\":[{\"titulo\":\"Melhorar eficiência operacional com automação\",\"krs\":[\"Automatizar 70% dos processos manuais atuais até Q4\",\"Diminuir erros operacionais em 50% até Q4\"]}],\"tarefas\":[{\"titulo\":\"Mapear processos operacionais manuais\",\"descricao\":\"**O que é:** Levantar todos os processos que ainda dependem de ações manuais.\\n\\n**Passo a Passo:**\\n1. Reunir equipe operacional para identificar processos.\\n2. Documentar processos, destacando atividades repetitivas.\\n\\n**Resultado Esperado:** Lista detalhada dos processos manuais para priorização.\",\"prazo\":\"2024-07-05\"},{\"titulo\":\"Selecionar ferramentas de automação\",\"descricao\":\"**O que é:** Avaliar soluções tecnológicas para automação dos processos identificados.\\n\\n**Passo a Passo:**\\n1. Pesquisa de mercado e análise de ferramentas.\\n2. Demonstrar opções para stakeholders.\\n\\n**Resultado Esperado:** Escolha da plataforma ideal para automação operacional.\",\"prazo\":\"2024-07-15\"},{\"titulo\":\"Desenvolver fluxos automatizados\",\"descricao\":\"**O que é:** Criar e testar automações baseadas nos processos selecionados.\\n\\n**Passo a Passo:**\\n1. Configurar scripts e integrações.\\n2. Realizar testes piloto.\\n\\n**Resultado Esperado:** Automação funcional em ambiente de teste.\",\"prazo\":\"2024-08-10\"},{\"titulo\":\"Treinar equipe na nova ferramenta\",\"descricao\":\"**O que é:** Capacitar os colaboradores para utilização da automação.\\n\\n**Passo a Passo:**\\n1. Preparar material didático.\\n2. Realizar oficinas práticas.\\n\\n**Resultado Esperado:** Equipe apta a operar o sistema automatizado.\",\"prazo\":\"2024-08-20\"},{\"titulo\":\"Implementar automação em produção\",\"descricao\":\"**O que é:** Migrar processos para o ambiente real garantindo estabilidade.\\n\\n**Passo a Passo:**\\n1. Planejar rollout gradual.\\n2. Monitorar indicadores e corrigir falhas.\\n\\n**Resultado Esperado:** Procura automatizada e estável em operação.\",\"prazo\":\"2024-09-05\"}]},{\"titulo\":\"Estratégia de Aquisição e Jornada do Cliente\",\"descricao\":\"Reformular as estratégias de aquisição com segmentação avançada e aprimorar a experiência do cliente para aumentar conversões e fidelização.\",\"prioridade\":\"alta\",\"okrs\":[{\"titulo\":\"Incrementar clientes qualificados e melhorar retenção\",\"krs\":[\"Aumentar captação de leads qualificados em 40% até Q4\",\"Elevar NPS em 20 pontos até Q4\"]}],\"tarefas\":[{\"titulo\":\"Analisar perfil dos clientes atuais\",\"descricao\":\"**O que é:** Entender melhor quem são os clientes para segmentar campanhas.\\n\\n**Passo a Passo:**\\n1. Coletar dados e feedbacks.\\n2. Criar personas detalhadas.\\n\\n**Resultado Esperado:** Base de personas para direcionamento das ações.\",\"prazo\":\"2024-07-03\"},{\"titulo\":\"Desenvolver campanhas segmentadas\",\"descricao\":\"**O que é:** Criar campanhas centradas nas personas definidas.\\n\\n**Passo a Passo:**\\n1. Planejar conteúdos e ofertas customizadas.\\n2. Implementar campanhas multi-canais.\\n\\n**Resultado Esperado:** Campanhas lançadas com mensagens personalizadas.\",\"prazo\":\"2024-07-25\"},{\"titulo\":\"Mapear jornada do cliente atual\",\"descricao\":\"**O que é:** Identificar todos os pontos de contato e experiências atuais dos clientes.\\n\\n**Passo a Passo:**\\n1. Levantar processos de onboarding e pós-venda.\\n2. Detectar gargalos e oportunidades.\\n\\n**Resultado Esperado:** Mapa visual da jornada com áreas de melhoria.\",\"prazo\":\"2024-07-15\"},{\"titulo\":\"Implementar ações de fidelização\",\"descricao\":\"**O que é:** Desenvolver programas para aumentar engajamento e retenção.\\n\\n**Passo a Passo:**\\n1. Criar planos de comunicação e ofertas exclusivas.\\n2. Monitorar satisfação e ajustar plano.\\n\\n**Resultado Esperado:** Programa ativo com indicadores de retenção positivos.\",\"prazo\":\"2024-08-20\"},{\"titulo\":\"Integrar feedbacks para melhoria contínua\",\"descricao\":\"**O que é:** Estabelecer rotina para coleta e implementação dos feedbacks dos clientes.\\n\\n**Passo a Passo:**\\n1. Criar canais de comunicação direta.\\n2. Analisar dados e executar ações corretivas.\\n\\n**Resultado Esperado:** Ciclo de melhoria contínua implantado na jornada do cliente.\",\"prazo\":\"2024-08-30\"}]},{\"titulo\":\"Engajamento e Capacitação da Equipe\",\"descricao\":\"Fortalecer a comunicação e aumentar a motivação e produtividade através de programas de capacitação e alinhamento interno.\",\"prioridade\":\"media\",\"okrs\":[{\"titulo\":\"Melhorar clima organizacional e desenvolvimento da equipe\",\"krs\":[\"Realizar 3 treinamentos até Q4 com satisfação mínima de 85%\",\"Reduzir índices de retrabalho em 30% até Q4\"]}],\"tarefas\":[{\"titulo\":\"Diagnosticar comunicação interna\",\"descricao\":\"**O que é:** Avaliar os canais atuais e identificar falhas.\\n\\n**Passo a Passo:**\\n1. Aplicar pesquisa com colaboradores.\\n2. Analisar resultados e canais existentes.\\n\\n**Resultado Esperado:** Relatório com gaps de comunicação interna.\",\"prazo\":\"2024-07-10\"},{\"titulo\":\"Desenvolver plano de comunicação interna\",\"descricao\":\"**O que é:** Criar estratégias para melhorar o fluxo e clareza das informações.\\n\\n**Passo a Passo:**\\n1. Planejar reuniões periódicas e canais oficiais.\\n2. Definir responsáveis pela comunicação.\\n\\n**Resultado Esperado:** Plano documentado e aprovado pela liderança.\",\"prazo\":\"2024-07-25\"},{\"titulo\":\"Planejar programa de capacitação e treinamentos\",\"descricao\":\"**O que é:** Preparar conteúdos para desenvolver habilidades críticas da equipe.\\n\\n**Passo a Passo:**\\n1. Identificar necessidades via avaliação de desempenho.\\n2. Criação e agendamento de treinamentos.\\n\\n**Resultado Esperado:** Calendário de treinamentos homologado.\",\"prazo\":\"2024-08-05\"},{\"titulo\":\"Realizar treinamentos práticos\",\"descricao\":\"**O que é:** Promover capacitações focadas em processos e soft skills.\\n\\n**Passo a Passo:**\\n1. Conduzir sessões presenciais ou online.\\n2. Aplicar avaliação para medir aprendizado.\\n\\n**Resultado Esperado:** Colaboradores treinados e feedback positivo.\",\"prazo\":\"2024-08-30\"},{\"titulo\":\"Monitorar resultados e ajustar ações\",\"descricao\":\"**O que é:** Avaliar impacto dos treinamentos e comunicação com métricas.\\n\\n**Passo a Passo:**\\n1. Acompanhar indicadores de produtividade e clima.\\n2. Realizar reuniões de ajuste com equipe.\\n\\n**Resultado Esperado:** Plano de continuidade ajustado conforme resultados.\",\"prazo\":\"2024-09-15\"}]}]'),
(50, 1, '2025-12-27 06:43:23', 50.00, 55.00, 50.00, 45, 'Em Crescimento', '<h3>🔍 O Cenário Atual</h3><p>A empresa apresenta processos básicos e intermediários em suas operações, demonstrando uma implementação inicial de controles financeiros e operacionais, porém ainda com alto potencial de melhoria. A aquisição de clientes e a jornada do cliente estão em estágios pouco estruturados, refletindo análise e estratégias pouco definidas, o que impacta diretamente a experiência e conversão. A equipe, ainda em desenvolvimento, demonstra capacidade, porém necessita de maior alinhamento e capacitação para elevar a maturidade geral.</p><h3>⚠️ Principais Gargalos</h3><ul><li>Processos operacionais ainda muito manuais, causando lentidão e retrabalho.</li><li>Baixa automação e controle financeiro dificultando a tomada de decisão ágil.</li><li>Estratégias de aquisição pouco definidas e com baixa efetividade.</li><li>Jornada do cliente pouco mapeada e otimizada, gerando perda de oportunidades e baixa retenção.</li><li>Equipe carece de treinamento focado e alinhamento estratégico, prejudicando execução.</li></ul><h3>🚀 O Caminho de Ouro</h3><p>Investir em automação dos processos operacionais e financeiros é urgente para garantir eficiência e rapidez nas entregas. Desenvolvimento de uma estratégia clara de aquisição combinada com a otimização da jornada do cliente permitirá crescimento consistente com maior retenção. Paralelamente, fortalecer a equipe por meio de capacitação alinhada às metas estratégicas será fundamental para viabilizar e sustentar as melhorias implementadas.</p>', 60, 40, '[{\"titulo\":\"Automatização Operacional e Financeira\",\"descricao\":\"Reduzir retrabalho e aumentar eficiência operacional com automação, além de implantar controles financeiros em tempo real para melhores decisões.\",\"prioridade\":\"alta\",\"okrs\":[{\"titulo\":\"Automatizar 80% dos processos operacionais e financeiros até o final do trimestre\",\"krs\":[\"Reduzir o tempo operacional em 50%\",\"Diminuir erros financeiros em 70%\"]}],\"tarefas\":[{\"titulo\":\"Mapear processos manuais atuais\",\"descricao\":\"**O que é:** Levantar todos os processos manuais existentes.\\n\\n**Passo a Passo:**\\n1. Entrevistar líderes de operação e financeiro.\\n2. Documentar fluxos atuais.\\n\\n**Resultado Esperado:** Mapa completo dos processos manuais em operação e financeiro.\",\"prazo\":\"2024-07-05\"},{\"titulo\":\"Selecionar ferramentas de automação\",\"descricao\":\"**O que é:** Escolher softwares que atendam às necessidades identificadas.\\n\\n**Passo a Passo:**\\n1. Analisar mercado.\\n2. Listar opções com custo-benefício.\\n3. Apresentar à diretoria.\\n\\n**Resultado Esperado:** Ferramentas selecionadas para implantação.\",\"prazo\":\"2024-07-12\"},{\"titulo\":\"Treinar equipe nas novas ferramentas\",\"descricao\":\"**O que é:** Preparar time para uso correto das ferramentas.\\n\\n**Passo a Passo:**\\n1. Criar plano de treinamento.\\n2. Realizar sessões práticas.\\n\\n**Resultado Esperado:** Equipe capacitada para operar automação.\",\"prazo\":\"2024-07-26\"},{\"titulo\":\"Implementar automação pilotos\",\"descricao\":\"**O que é:** Testar automação em processos selecionados.\\n\\n**Passo a Passo:**\\n1. Definir processos pilotos.\\n2. Configurar ferramentas.\\n3. Monitorar resultados.\\n\\n**Resultado Esperado:** Pilotos automatizados e avaliados.\",\"prazo\":\"2024-08-09\"},{\"titulo\":\"Analisar indicadores pós-automação\",\"descricao\":\"**O que é:** Medir impacto da automação nos KPIs.\\n\\n**Passo a Passo:**\\n1. Coletar dados antes e depois.\\n2. Comparar e reportar resultados.\\n\\n**Resultado Esperado:** Relatório de eficiência e melhorias obtidas.\",\"prazo\":\"2024-08-23\"}]},{\"titulo\":\"Estratégia de Aquisição e Otimização da Jornada\",\"descricao\":\"Definir e implementar estratégias eficazes para potencializar aquisição de clientes e melhorar a experiência ao longo da jornada, aumentando conversão e retenção.\",\"prioridade\":\"alta\",\"okrs\":[{\"titulo\":\"Aumentar a taxa de conversão de aquisição em 30% e melhorar NPS em 20%\",\"krs\":[\"Mapear 100% da jornada do cliente atual\",\"Implementar ao menos 3 melhorias na jornada até o final do projeto\"]}],\"tarefas\":[{\"titulo\":\"Mapear jornada do cliente\",\"descricao\":\"**O que é:** Diagnosticar todas etapas até a fidelização.\\n\\n**Passo a Passo:**\\n1. Coletar feedbacks e analisar pontos de contato.\\n2. Criar fluxograma detalhado.\\n\\n**Resultado Esperado:** Mapa da jornada atualizado e completo.\",\"prazo\":\"2024-07-07\"},{\"titulo\":\"Realizar análise de gaps na aquisição\",\"descricao\":\"**O que é:** Entender pontos frágeis na atual estratégia.\\n\\n**Passo a Passo:**\\n1. Revisar canais e campanhas existentes.\\n2. Medir performance e retorno.\\n\\n**Resultado Esperado:** Diagnóstico apontando falhas e oportunidades.\",\"prazo\":\"2024-07-14\"},{\"titulo\":\"Desenvolver plano de melhoria na jornada\",\"descricao\":\"**O que é:** Criar ações pontuais para aprimorar experiência.\\n\\n**Passo a Passo:**\\n1. Priorizar melhorias com base no impacto.\\n2. Definir responsáveis e cronograma.\\n\\n**Resultado Esperado:** Plano formalizado para execução.\",\"prazo\":\"2024-07-21\"},{\"titulo\":\"Implementar melhorias aprovadas\",\"descricao\":\"**O que é:** Colocar em prática as ações planejadas.\\n\\n**Passo a Passo:**\\n1. Executar melhorias nos canais e processos.\\n2. Monitorar resultados iniciais.\\n\\n**Resultado Esperado:** Melhorias visíveis e funcionando na jornada.\",\"prazo\":\"2024-08-11\"},{\"titulo\":\"Treinar equipe de vendas e atendimento\",\"descricao\":\"**O que é:** Alinhar time para nova abordagem da jornada.\\n\\n**Passo a Passo:**\\n1. Preparar material de treinamento.\\n2. Realizar sessões práticas e feedback.\\n\\n**Resultado Esperado:** Equipe engajada e preparada para nova jornada.\",\"prazo\":\"2024-08-18\"}]},{\"titulo\":\"Capacitação e Alinhamento da Equipe\",\"descricao\":\"Fortalecer a performance do time por meio de treinamentos e alinhamento estratégico, garantindo maior produtividade e engajamento frente às novas demandas.\",\"prioridade\":\"media\",\"okrs\":[{\"titulo\":\"Elevar maturidade da equipe para nível profissional (score >75) em 6 meses\",\"krs\":[\"Realizar 4 treinamentos relevantes com 90% de participação\",\"Implementar processo contínuo de feedback e acompanhamento mensal\"]}],\"tarefas\":[{\"titulo\":\"Diagnosticar necessidades de treinamento\",\"descricao\":\"**O que é:** Avaliar lacunas de habilidades atuais.\\n\\n**Passo a Passo:**\\n1. Aplicar pesquisas e entrevistas.\\n2. Analisar gaps identificados.\\n\\n**Resultado Esperado:** Relatório com necessidades específicas.\",\"prazo\":\"2024-07-10\"},{\"titulo\":\"Planejar calendário de treinamentos\",\"descricao\":\"**O que é:** Definir tópicos e datas para capacitação.\\n\\n**Passo a Passo:**\\n1. Selecionar conteúdos prioritários.\\n2. Agendar sessões e divulgar.\\n\\n**Resultado Esperado:** Cronograma oficial de treinamentos.\",\"prazo\":\"2024-07-17\"},{\"titulo\":\"Realizar workshops e treinamentos\",\"descricao\":\"**O que é:** Oferecer capacitações práticas e teóricas.\\n\\n**Passo a Passo:**\\n1. Ministrar treinamentos conforme agenda.\\n2. Promover dinâmicas de engajamento.\\n\\n**Resultado Esperado:** Equipe atualizada e motivada.\",\"prazo\":\"2024-08-21\"},{\"titulo\":\"Implantar sistema de feedback contínuo\",\"descricao\":\"**O que é:** Criar rotina para avaliação e apoio constante.\\n\\n**Passo a Passo:**\\n1. Definir critérios e frequência.\\n2. Treinar líderes para conduzir.\\n\\n**Resultado Esperado:** Processo ativo de feedback funcionando.\",\"prazo\":\"2024-08-30\"},{\"titulo\":\"Monitorar evolução e ajustar programa\",\"descricao\":\"**O que é:** Medir impacto dos treinamentos e promover melhorias.\\n\\n**Passo a Passo:**\\n1. Aplicar pesquisas de satisfação e avaliação.\\n2. Atualizar calendário conforme resultados.\\n\\n**Resultado Esperado:** Programa dinâmico e eficaz para equipe.\",\"prazo\":\"2024-09-30\"}]}]'),
(51, 1, '2025-12-27 14:44:22', 51.00, 55.00, 40.00, 65, 'Em Crescimento', '<h3>🔍 O Cenário Atual</h3><p>A empresa apresenta um cenário misto com processos em sua maioria básicos ou parcialmente estruturados. O operacional e aquisição possuem alguma automação inicial, porém carecem de integração e padronização mais avançada. Financeiro e equipe demonstram fragilidades maiores, principalmente em processos manuais repetitivos e falta de governança clara. A jornada do cliente está subutilizada, promovendo perda de oportunidades de engajamento e retenção.</p><h3>⚠️ Principais Gargalos</h3><ul><li>Processos financeiros manuais e falta de controle em fluxo de caixa e previsão.</li><li>Falhas no acompanhamento e na geração de leads qualificados no processo de aquisição.</li><li>Comunicação e alinhamento pouco eficazes dentro da equipe, impactando produtividade.</li><li>Jornada do cliente pouco mapeada e com baixa automação, reduzindo a experiência e retenção.</li></ul><h3>🚀 O Caminho de Ouro</h3><p>Investir na automação dos processos financeiros e no fortalecimento da governança ajudará a mitigar riscos e garantir maior previsibilidade. Paralelamente, implementar um funil robusto de aquisição aliado a uma jornada de cliente bem estruturada e acompanhada com tecnologia proporcionará aumento expressivo na conversão e satisfação dos clientes. Por fim, promover alinhamento e capacitação frequente da equipe criará um ambiente colaborativo e eficiente, elemento vital para sustentação do crescimento.</p>', 45, 50, '[{\"titulo\":\"Automatização Financeira e Controle\",\"descricao\":\"Reduzir erros, aumentar a precisão no fluxo de caixa e a previsibilidade financeira por meio da automação e implementação de governança financeira.\",\"prioridade\":\"alta\",\"okrs\":[{\"titulo\":\"Dinâmica Financeira Automatizada e Controlada\",\"krs\":[\"Reduzir em 80% as tarefas manuais financeiras em 3 meses\",\"Implementar relatório semanal de fluxo de caixa com precisão acima de 95% em 90 dias\"]}],\"tarefas\":[{\"titulo\":\"Mapear processos financeiros atuais\",\"descricao\":\"**O que é:** Levantar e documentar todos os processos financeiros existentes.\\n\\n**Passo a Passo:**\\n1. Entrevistar equipe financeira.\\n2. Identificar pontos manuais e principais gargalos.\\n\\n**Resultado Esperado:** Documento com mapeamento completo dos processos financeiros.\\n\",\"prazo\":\"2024-07-10\"},{\"titulo\":\"Selecionar ferramenta de automação financeira\",\"descricao\":\"**O que é:** Avaliar e escolher software ideal para automatizar processos financeiros.\\n\\n**Passo a Passo:**\\n1. Levantar requisitos.\\n2. Fazer demonstrações e análise custo-benefício.\\n3. Definir ferramenta.\\n\\n**Resultado Esperado:** Escolha da ferramenta para automação financeira.\\n\",\"prazo\":\"2024-07-17\"},{\"titulo\":\"Treinar equipe na ferramenta escolhida\",\"descricao\":\"**O que é:** Capacitar time financeiro para utilização plena da nova solução.\\n\\n**Passo a Passo:**\\n1. Preparar material de treinamento.\\n2. Realizar workshops práticos.\\n\\n**Resultado Esperado:** Equipe apta a utilizar a ferramenta com autonomia.\\n\",\"prazo\":\"2024-07-31\"},{\"titulo\":\"Implementar controle e monitoramento de fluxo de caixa\",\"descricao\":\"**O que é:** Estruturar controle diário e semanal do fluxo de caixa.\\n\\n**Passo a Passo:**\\n1. Definir indicadores e dashboards.\\n2. Automatizar geração e envio de relatórios.\\n\\n**Resultado Esperado:** Fluxo de caixa monitorado em tempo real e relatórios acessíveis.\\n\",\"prazo\":\"2024-08-15\"},{\"titulo\":\"Documentar políticas e governança financeira\",\"descricao\":\"**O que é:** Criar normas para regular processos e responsabilidades financeiras.\\n\\n**Passo a Passo:**\\n1. Definir regras internas.\\n2. Validar com liderança.\\n3. Divulgar e treinar time.\\n\\n**Resultado Esperado:** Manual de governança financeira institucionalizado.\\n\",\"prazo\":\"2024-08-20\"}]},{\"titulo\":\"Otimização da Aquisição e Jornada do Cliente\",\"descricao\":\"Melhorar captação e qualificações de leads, junto ao mapeamento e automação da jornada do cliente para aumentar conversão e engajamento.\",\"prioridade\":\"alta\",\"okrs\":[{\"titulo\":\"Aumento de Leads Qualificados e Engajamento\",\"krs\":[\"Elevar em 50% a taxa de conversão de leads em 4 meses\",\"Implantar jornada automatizada com 70% de engajamento ativo dentro de 3 meses\"]}],\"tarefas\":[{\"titulo\":\"Mapear funil de aquisição atual\",\"descricao\":\"**O que é:** Analisar todas as etapas atuais de aquisição de clientes.\\n\\n**Passo a Passo:**\\n1. Levantar canais e estratégias.\\n2. Diagnosticar pontos de fuga e baixa performance.\\n\\n**Resultado Esperado:** Documento detalhado do funil atual e seus gaps.\\n\",\"prazo\":\"2024-07-10\"},{\"titulo\":\"Desenhar jornada ideal do cliente\",\"descricao\":\"**O que é:** Construir mapa da jornada completa para guiar ações e comunicação.\\n\\n**Passo a Passo:**\\n1. Identificar momentos-chave do cliente.\\n2. Definir interações e conteúdo para cada etapa.\\n\\n**Resultado Esperado:** Mapa visual da jornada do cliente alinhado aos objetivos de negócio.\\n\",\"prazo\":\"2024-07-20\"},{\"titulo\":\"Configurar automação de marketing e CRM\",\"descricao\":\"**O que é:** Implantar ferramentas que automatizem o relacionamento e nutrição de leads.\\n\\n**Passo a Passo:**\\n1. Selecionar plataforma e customizar.\\n2. Integrar com canais de comunicação.\\n\\n**Resultado Esperado:** Sistema automatizado e integrado funcionando para nutrição ativa.\\n\",\"prazo\":\"2024-08-05\"},{\"titulo\":\"Treinar equipe de aquisição e atendimento\",\"descricao\":\"**O que é:** Capacitar o time para uso das novas ferramentas e abordagem.\\n\\n**Passo a Passo:**\\n1. Desenvolver treinamentos práticos.\\n2. Simular processos com equipe.\\n\\n**Resultado Esperado:** Time alinhado e capacitado para operar novas estratégias.\\n\",\"prazo\":\"2024-08-15\"},{\"titulo\":\"Monitorar e ajustar campanhas e jornada\",\"descricao\":\"**O que é:** Acompanhar resultados e promover ajustes iterativos.\\n\\n**Passo a Passo:**\\n1. Criar dashboards para monitoramento.\\n2. Realizar reuniões semanais de análise.\\n\\n**Resultado Esperado:** Incrementos constantes na captação e engajamento via otimização contínua.\\n\",\"prazo\":\"2024-09-10\"}]},{\"titulo\":\"Fortalecimento e Alinhamento da Equipe\",\"descricao\":\"Melhorar comunicação interna, capacitação e engajamento da equipe para gerar maior produtividade e clima organizacional positivo.\",\"prioridade\":\"media\",\"okrs\":[{\"titulo\":\"Equipe Alinhada e Motivada\",\"krs\":[\"Realizar 3 treinamentos de capacitação até o final do trimestre\",\"Aumentar o índice de satisfação interna em 30% em 4 meses\"]}],\"tarefas\":[{\"titulo\":\"Diagnosticar comunicação interna atual\",\"descricao\":\"**O que é:** Avaliar meios e fluxos de comunicação entre os colaboradores.\\n\\n**Passo a Passo:**\\n1. Aplicar pesquisa interna.\\n2. Mapear canais e gargalos.\\n\\n**Resultado Esperado:** Relatório com análise da comunicação existente.\\n\",\"prazo\":\"2024-07-10\"},{\"titulo\":\"Planejar programa de capacitação contínua\",\"descricao\":\"**O que é:** Criar cronograma e conteúdo para treinamentos relevantes.\\n\\n**Passo a Passo:**\\n1. Identificar necessidades da equipe.\\n2. Definir temas e cronograma.\\n\\n**Resultado Esperado:** Plano detalhado de capacitação trimestral.\\n\",\"prazo\":\"2024-07-15\"},{\"titulo\":\"Implementar reuniões regulares de alinhamento\",\"descricao\":\"**O que é:** Estabelecer rotina de encontros para alinhamento e feedback.\\n\\n**Passo a Passo:**\\n1. Definir frequência e formato.\\n2. Convocar equipes e conduzir reuniões.\\n\\n**Resultado Esperado:** Reuniões implementadas e em curso.\\n\",\"prazo\":\"2024-07-20\"},{\"titulo\":\"Iniciar treinamentos práticos\",\"descricao\":\"**O que é:** Executar os treinamentos planejados para desenvolvimento de skills.\\n\\n**Passo a Passo:**\\n1. Preparar materiais e instrutores.\\n2. Realizar sessões com participação ativa.\\n\\n**Resultado Esperado:** Colaboradores capacitados com novas habilidades.\\n\",\"prazo\":\"2024-08-10\"},{\"titulo\":\"Monitorar clima organizacional\",\"descricao\":\"**O que é:** Acompanhar a satisfação interna e clima organizacional.\\n\\n**Passo a Passo:**\\n1. Aplicar pesquisa de clima.\\n2. Analisar dados e propor melhorias.\\n\\n**Resultado Esperado:** Diagnóstico atualizado do clima e ações corretivas sugeridas.\\n\",\"prazo\":\"2024-09-01\"}]}]');
INSERT INTO `gestao_diagnostico_resultados` (`id`, `user_id`, `data_realizacao`, `score_geral`, `score_operacao`, `score_financeiro`, `score_aquisicao`, `nivel_maturidade`, `analise_ia`, `score_equipe`, `score_jornada`, `sugestao_projetos`) VALUES
(52, 1, '2025-12-27 16:38:20', 50.00, 55.00, 45.00, 60, 'Em Crescimento', '<h3>🔍 O Cenário Atual</h3> <p>A empresa apresenta uma maturidade operacional e de aquisição no nível intermediário, com processos ainda dependentes de ações manuais e pouca integração tecnológica. O setor financeiro demonstra dificuldades em controles e planejamento de fluxo, enquanto a equipe enfrenta falhas na comunicação e baixa retenção de talentos. A jornada do cliente ainda carece de melhorias estratégicas para elevar a satisfação e conversão.</p> <h3>⚠️ Principais Gargalos</h3> <ul><li>Processos operacionais fragmentados, dificultando a agilidade e controle.</li><li>Planejamento financeiro insuficiente, com baixa automação e monitoramento das finanças.</li><li>Equipe sobrecarregada e baixa capacitação, levando a falhas e turnover elevado.</li></ul> <h3>🚀 O Caminho de Ouro</h3> <p>Automatizar e integrar processos-chave, tanto operacionais quanto financeiros, será fundamental para elevar a performance e reduzir erros. Investir no desenvolvimento e engajamento da equipe, junto a projetos de aquisição digital aprimorados, permitirá escalar o negócio com qualidade e foco no cliente, gerando crescimento sustentável e lucrativo.</p>', 40, 50, '[{\"titulo\":\"Automatização e Integração Operacional\",\"descricao\":\"Melhorar a eficiência operacional reduzindo tarefas manuais e integrando sistemas para garantir maior agilidade e controle dos processos internos.\",\"prioridade\":\"alta\",\"okrs\":[{\"titulo\":\"Automatizar 80% dos processos manuais operacionais\",\"krs\":[\"Reduzir o tempo médio de execução dos processos internos em 40%\",\"Integrar 3 sistemas críticos em uma plataforma única\"]}],\"tarefas\":[{\"titulo\":\"Mapear processos operacionais atuais\",\"descricao\":\"**O que é:** Levantamento detalhado dos processos internos para identificar gargalos e oportunidades de automação.\\n\\n**Passo a Passo:**\\n1. Reunir equipe operacional para levantamento.\\n2. Documentar fluxos de atividades.\\n3. Validar mapeamento com stakeholders.\\n\\n**Resultado Esperado:** Fluxograma completo dos processos operacionais atuais até 2026-01-10.\",\"prazo\":\"2026-01-10\"},{\"titulo\":\"Selecionar ferramenta de automação compatível\",\"descricao\":\"**O que é:** Pesquisa e avaliação de plataformas tecnológicas para automação e integração dos processos.\\n\\n**Passo a Passo:**\\n1. Definir critérios técnicos e financeiros.\\n2. Fazer benchmark de ferramentas.\\n3. Apresentar relatório para decisão da diretoria.\\n\\n**Resultado Esperado:** Relatório com recomendação de ferramenta até 2026-01-20.\",\"prazo\":\"2026-01-20\"},{\"titulo\":\"Configurar e implementar automações iniciais\",\"descricao\":\"**O que é:** Configuração da plataforma escolhida para automatizar os processos mais críticos.\\n\\n**Passo a Passo:**\\n1. Treinamento da equipe técnica.\\n2. Desenvolvimento das automações.\\n3. Testes e ajustes.\\n\\n**Resultado Esperado:** Processos piloto automatizados até 2026-02-15.\",\"prazo\":\"2026-02-15\"},{\"titulo\":\"Treinar equipe operacional nas novas ferramentas\",\"descricao\":\"**O que é:** Capacitação da equipe para utilização eficiente dos sistemas de automação.\\n\\n**Passo a Passo:**\\n1. Criar material didático e tutoriais.\\n2. Realizar workshops e sessões práticas.\\n3. Avaliar compreensão dos usuários.\\n\\n**Resultado Esperado:** Treinamento concluído com 90% de satisfação até 2026-02-28.\",\"prazo\":\"2026-02-28\"},{\"titulo\":\"Monitorar indicadores operacionais pós-implementação\",\"descricao\":\"**O que é:** Acompanhar os KPIs para avaliar a eficácia das automações implantadas.\\n\\n**Passo a Passo:**\\n1. Definir KPIs relevantes.\\n2. Coletar dados contínuos.\\n3. Realizar reuniões mensais para análise.\\n\\n**Resultado Esperado:** Relatórios mensais com melhorias e recomendações até 2026-03-31.\",\"prazo\":\"2026-03-31\"},{\"titulo\":\"Expandir automação para demais processos críticos\",\"descricao\":\"**O que é:** Aplicar aprendizados e ampliar a automação para outras áreas operacionais.\\n\\n**Passo a Passo:**\\n1. Priorizar processos adicionais.\\n2. Desenvolver automações.\\n3. Realizar treinamentos contínuos.\\n\\n**Resultado Esperado:** 80% dos processos manuais automatizados até 2026-06-30.\",\"prazo\":\"2026-06-30\"},{\"titulo\":\"Documentar processos atualizados e treinamentos\",\"descricao\":\"**O que é:** Produção de manual interno atualizado com os novos processos e guias para equipes.\\n\\n**Passo a Passo:**\\n1. Registrar procedimentos pós-automação.\\n2. Criar documentos e vídeos explicativos.\\n3. Disponibilizar em plataforma acessível.\\n\\n**Resultado Esperado:** Material disponível para toda a equipe até 2026-04-15.\",\"prazo\":\"2026-04-15\"},{\"titulo\":\"Estabelecer rotina de revisão contínua dos processos\",\"descricao\":\"**O que é:** Implantar ciclos de melhoria contínua para manter a operação otimizada.\\n\\n**Passo a Passo:**\\n1. Criar comitê de processos.\\n2. Programar revisões periódicas.\\n3. Implementar feedback das equipes.\\n\\n**Resultado Esperado:** Plano de revisão aprovado e em execução até 2026-05-15.\",\"prazo\":\"2026-05-15\"},{\"titulo\":\"Comunicar avanços para toda a empresa\",\"descricao\":\"**O que é:** Garantir transparência e engajamento comunicando os resultados das automações.\\n\\n**Passo a Passo:**\\n1. Criar newsletters internas.\\n2. Realizar reuniões gerais de alinhamento.\\n3. Recolher feedbacks dos colaboradores.\\n\\n**Resultado Esperado:** Comunicação eficiente com mais de 85% de engajamento até 2026-02-28.\",\"prazo\":\"2026-02-28\"},{\"titulo\":\"Mensurar impacto financeiro da automação\",\"descricao\":\"**O que é:** Avaliar o retorno financeiro e ganhos de produtividade gerados pelo projeto.\\n\\n**Passo a Passo:**\\n1. Levantar custos e investimentos.\\n2. Quantificar ganhos em tempo e qualidade.\\n3. Apresentar relatório para diretoria.\\n\\n**Resultado Esperado:** Relatório consolidado com ROI até 2026-07-31.\",\"prazo\":\"2026-07-31\"}]},{\"titulo\":\"Reestruturação Financeira e Controle\",\"descricao\":\"Fortalecer o planejamento financeiro e automatizar controles para melhorar a saúde financeira e planejamento estratégico da empresa.\",\"prioridade\":\"alta\",\"okrs\":[{\"titulo\":\"Garantir controle financeiro completo e atualizado em tempo real\",\"krs\":[\"Reduzir erros no registro financeiro para menos de 2% ao mês\",\"Implementar sistema de acompanhamento financeiro com atualizações diárias\"]}],\"tarefas\":[{\"titulo\":\"Realizar diagnóstico detalhado dos processos financeiros\",\"descricao\":\"**O que é:** Mapeamento dos processos atuais para identificar falhas e gargalos.\\n\\n**Passo a Passo:**\\n1. Levantar fluxos financeiros existentes.\\n2. Identificar pontos críticos.\\n3. Validar com equipe financeira.\\n\\n**Resultado Esperado:** Diagnóstico completo até 2026-01-15.\",\"prazo\":\"2026-01-15\"},{\"titulo\":\"Definir indicadores financeiros estratégicos\",\"descricao\":\"**O que é:** Selecionar KPIs fundamentais para controle e planejamento.\\n\\n**Passo a Passo:**\\n1. Revisar necessidades da diretoria.\\n2. Selecionar indicadores mensuráveis.\\n3. Formalizar indicadores para monitoramento.\\n\\n**Resultado Esperado:** Lista aprovada de KPIs até 2026-01-25.\",\"prazo\":\"2026-01-25\"},{\"titulo\":\"Selecionar ferramenta de gestão financeira integrada\",\"descricao\":\"**O que é:** Escolha de software para controle financeiro automatizado.\\n\\n**Passo a Passo:**\\n1. Avaliar opções no mercado.\\n2. Realizar testes-piloto.\\n3. Reportar recomendação para decisão.\\n\\n**Resultado Esperado:** Ferramenta homologada até 2026-02-15.\",\"prazo\":\"2026-02-15\"},{\"titulo\":\"Configurar sistema de contas a pagar e receber automático\",\"descricao\":\"**O que é:** Implantar processos automatizados para cobranças e pagamentos.\\n\\n**Passo a Passo:**\\n1. Configurar integrações bancárias.\\n2. Criar alertas e notificações.\\n3. Realizar testes operacionais.\\n\\n**Resultado Esperado:** Sistema funcionando até 2026-03-01.\",\"prazo\":\"2026-03-01\"},{\"titulo\":\"Capacitar equipe financeira em controle automatizado\",\"descricao\":\"**O que é:** Treinamento para uso da nova plataforma e controle financeiro.\\n\\n**Passo a Passo:**\\n1. Preparar material de treinamento.\\n2. Realizar workshops práticos.\\n3. Avaliar domínio pelo time.\\n\\n**Resultado Esperado:** Equipe treinada até 2026-03-15.\",\"prazo\":\"2026-03-15\"},{\"titulo\":\"Implementar planejamento orçamentário anual com revisões trimestrais\",\"descricao\":\"**O que é:** Estruturar planos financeiros baseados em metas e revisá-los periodicamente.\\n\\n**Passo a Passo:**\\n1. Definir metas anuais.\\n2. Criar cronograma de revisões.\\n3. Apresentar e ajustar orçamentos.\\n\\n**Resultado Esperado:** Plano aprovado e em vigor até 2026-02-28.\",\"prazo\":\"2026-02-28\"},{\"titulo\":\"Automatizar relatórios financeiros semanais\",\"descricao\":\"**O que é:** Gerar relatórios financeiros regulares para acompanhamento atualizado.\\n\\n**Passo a Passo:**\\n1. Definir escopo dos relatórios.\\n2. Configurar geração automática.\\n3. Validar precisão dos dados.\\n\\n**Resultado Esperado:** Relatórios automatizados até 2026-03-10.\",\"prazo\":\"2026-03-10\"},{\"titulo\":\"Criar plano de contingência financeira\",\"descricao\":\"**O que é:** Estabelecer ações para momentos de crise ou imprevistos financeiros.\\n\\n**Passo a Passo:**\\n1. Identificar riscos financeiros.\\n2. Desenvolver estratégias mitigadoras.\\n3. Treinar equipe para execução.\\n\\n**Resultado Esperado:** Plano documentado até 2026-04-01.\",\"prazo\":\"2026-04-01\"},{\"titulo\":\"Integrar dados financeiros com sistema operacional\",\"descricao\":\"**O que é:** Conectar sistemas para garantir dados sincronizados e confiáveis.\\n\\n**Passo a Passo:**\\n1. Mapear integrações necessárias.\\n2. Desenvolver APIs ou usar ferramentas.\\n3. Testar fluxo de dados.\\n\\n**Resultado Esperado:** Integração efetiva até 2026-05-10.\",\"prazo\":\"2026-05-10\"},{\"titulo\":\"Monitorar e revisar controles financeiros mensalmente\",\"descricao\":\"**O que é:** Acompanhar o funcionamento dos controles implantados e corrigir desvios.\\n\\n**Passo a Passo:**\\n1. Definir responsáveis pela análise.\\n2. Realizar reuniões mensais.\\n3. Ajustar processos conforme feedback.\\n\\n**Resultado Esperado:** Rotina operacionalizada para monitoramento contínuo até 2026-04-30.\",\"prazo\":\"2026-04-30\"}]},{\"titulo\":\"Desenvolvimento e Engajamento da Equipe\",\"descricao\":\"Fortalecer a capacitação, comunicação interna e clima organizacional para melhorar a retenção e produtividade da equipe.\",\"prioridade\":\"media\",\"okrs\":[{\"titulo\":\"Reduzir turnover em 30% e aumentar satisfação interna para 80%\",\"krs\":[\"Realizar programa de treinamento para 100% da equipe\",\"Implementar canais de comunicação saudável com 90% de adesão\"]}],\"tarefas\":[{\"titulo\":\"Realizar diagnóstico de clima e competências da equipe\",\"descricao\":\"**O que é:** Levantamento das percepções e necessidades do time.\\n\\n**Passo a Passo:**\\n1. Aplicar pesquisa de clima.\\n2. Avaliar gaps de competências.\\n3. Consolidar relatório de resultados.\\n\\n**Resultado Esperado:** Relatório diagnóstico até 2026-01-20.\",\"prazo\":\"2026-01-20\"},{\"titulo\":\"Planejar programa de capacitação contínua\",\"descricao\":\"**O que é:** Estruturar cronograma e conteúdo para desenvolvimento de habilidades.\\n\\n**Passo a Passo:**\\n1. Selecionar temas prioritários.\\n2. Definir formatos (workshops, e-learning).\\n3. Programar sessões mensais.\\n\\n**Resultado Esperado:** Plano anual de treinamentos até 2026-02-10.\",\"prazo\":\"2026-02-10\"},{\"titulo\":\"Implementar canal de comunicação interna eficaz\",\"descricao\":\"**O que é:** Criar meio formal e informal para interação e alinhamento.\\n\\n**Passo a Passo:**\\n1. Escolher plataforma adequada.\\n2. Treinar líderes para uso.\\n3. Incentivar participação de todos.\\n\\n**Resultado Esperado:** Canal ativo com 90% de engajamento até 2026-03-01.\",\"prazo\":\"2026-03-01\"},{\"titulo\":\"Promover workshops de integração e cultura organizacional\",\"descricao\":\"**O que é:** Fortalecer vínculo e entendimento dos valores da empresa.\\n\\n**Passo a Passo:**\\n1. Definir conteúdos e facilitadores.\\n2. Realizar encontros mensais.\\n3. Medir impacto via feedbacks.\\n\\n**Resultado Esperado:** Workshops realizados mensalmente a partir de 2026-02-20.\",\"prazo\":\"2026-02-20\"},{\"titulo\":\"Criar programa de reconhecimento e incentivo\",\"descricao\":\"**O que é:** Implantar sistema para valorizar conquistas e motivar desempenho.\\n\\n**Passo a Passo:**\\n1. Definir critérios de reconhecimento.\\n2. Comunicar processo para equipe.\\n3. Executar reconhecimento trimestral.\\n\\n**Resultado Esperado:** Programa institucionalizado até 2026-04-15.\",\"prazo\":\"2026-04-15\"},{\"titulo\":\"Desenvolver plano de carreira e sucessão\",\"descricao\":\"**O que é:** Estruturar trajetórias profissionais claras e oportunidades de crescimento.\\n\\n**Passo a Passo:**\\n1. Mapear cargos e competências.\\n2. Definir critérios de progressão.\\n3. Comunicar plano para todos.\\n\\n**Resultado Esperado:** Documento formalizado e divulgado até 2026-05-10.\",\"prazo\":\"2026-05-10\"},{\"titulo\":\"Realizar reuniões de feedback regulares\",\"descricao\":\"**O que é:** Estabelecer rotina de comunicação bidirecional para acompanhar desempenho.\\n\\n**Passo a Passo:**\\n1. Treinar líderes para feedbacks construtivos.\\n2. Agendar encontros mensais.\\n3. Registrar pontos de melhoria.\\n\\n**Resultado Esperado:** Processo implementado a partir de 2026-02-28.\",\"prazo\":\"2026-02-28\"},{\"titulo\":\"Monitorar KPIs de rotatividade e engajamento\",\"descricao\":\"**O que é:** Acompanhar indicadores para medir evolução da área.\\n\\n**Passo a Passo:**\\n1. Definir métricas-chave.\\n2. Coletar dados mensalmente.\\n3. Analisar e reportar periodicamente.\\n\\n**Resultado Esperado:** Relatórios mensais produzidos a partir de 2026-03-15.\",\"prazo\":\"2026-03-15\"},{\"titulo\":\"Implementar pesquisa semestral de clima organizacional\",\"descricao\":\"**O que é:** Reavaliar ambiente e percepção dos colaboradores para ajustes contínuos.\\n\\n**Passo a Passo:**\\n1. Elaborar questionário.\\n2. Aplicar pesquisa.\\n3. Apresentar resultados e plano de ação.\\n\\n**Resultado Esperado:** Pesquisa aplicada e reportada a cada seis meses, primeira até 2026-06-30.\",\"prazo\":\"2026-06-30\"},{\"titulo\":\"Promover ações de saúde mental e bem-estar\",\"descricao\":\"**O que é:** Implementar atividades para melhorar qualidade de vida da equipe.\\n\\n**Passo a Passo:**\\n1. Identificar necessidades.\\n2. Programar palestras e workshops.\\n3. Fornecer suporte profissional.\\n\\n**Resultado Esperado:** Plano implementado até 2026-04-30.\",\"prazo\":\"2026-04-30\"}]}]');

