INSERT INTO `gestao_projetos` (`id`, `diagnostico_id`, `titulo`, `descricao`, `status`, `prioridade`, `data_inicio`, `data_fim_prevista`, `responsavel_id`, `created_at`, `updated_at`) VALUES
(18, 42, 'Automatização de Processos Operacionais', 'Automatizar e padronizar os processos operacionais para aumentar eficiência, reduzir erros e agilizar entregas, melhorando a qualidade do serviço e a satisfação do cliente.', 'planejamento', 'alta', '2025-12-27', NULL, 1, '2025-12-27 08:55:09', '2025-12-27 08:55:09'),
(19, 42, 'Reestruturação Financeira e Controle de Aquisição', 'Melhorar o controle financeiro e os processos de aquisição para reduzir custos, evitar desperdícios e garantir melhor planejamento orçamentário, aumentando a sustentabilidade do negócio.', 'planejamento', 'media', '2025-12-27', NULL, 1, '2025-12-27 08:55:12', '2025-12-27 08:55:12'),
(20, 42, 'Desenvolvimento e Gestão de Equipe', 'Estruturar práticas de gestão de pessoas e capacitar a equipe para aumentar engajamento, produtividade e retenção de talentos, alinhando a equipe aos objetivos estratégicos da empresa.', 'planejamento', 'media', '2025-12-27', NULL, 1, '2025-12-27 08:55:13', '2025-12-27 08:55:13'),
(21, 44, 'Automatização de Processos Operacionais', 'Automatizar os processos operacionais para reduzir erros manuais, melhorar eficiência e permitir escalabilidade da operação.', 'planejamento', 'alta', '2025-12-27', NULL, 1, '2025-12-27 09:00:30', '2025-12-27 09:00:30'),
(22, 44, 'Fortalecimento da Gestão Financeira', 'Estruturar a área financeira com controles rígidos e planejamento para garantir saúde financeira e melhores decisões.', 'planejamento', 'media', '2025-12-27', NULL, 1, '2025-12-27 09:00:30', '2025-12-27 09:00:30'),
(23, 44, 'Revitalização da Aquisição de Clientes', 'Desenvolver uma abordagem estruturada para aquisição focada em métricas, canais e técnicas eficazes para ampliar a base de clientes.', 'planejamento', 'alta', '2025-12-27', NULL, 1, '2025-12-27 09:00:31', '2025-12-27 09:00:31'),
(24, 46, 'Automação Operacional e Financeira', 'Automatizar processos operacionais e financeiros para reduzir erros, aumentar a eficiência e melhorar a tomada de decisão.', 'planejamento', 'alta', '2025-12-27', NULL, 1, '2025-12-27 09:32:00', '2025-12-27 09:32:00'),
(25, 46, 'Estratégia Efetiva de Aquisição', 'Desenvolver e implementar uma estratégia estruturada de aquisição para ampliar e qualificar a base de clientes.', 'planejamento', 'alta', '2025-12-27', NULL, 1, '2025-12-27 09:32:00', '2025-12-27 09:32:00'),
(26, 46, 'Mapeamento e Otimização da Jornada do Cliente', 'Identificar pontos críticos na jornada do cliente para aumentar satisfação, engajamento e retenção.', 'planejamento', 'media', '2025-12-27', NULL, 1, '2025-12-27 09:32:01', '2025-12-27 09:32:01'),
(27, 49, 'Automatização Operacional Integrada', 'Automatizar processos críticos para aumentar eficiência, reduzir erros e liberar a equipe para atividades estratégicas.', 'planejamento', 'alta', '2025-12-27', NULL, 1, '2025-12-27 09:41:16', '2025-12-27 09:41:16'),
(28, 49, 'Engajamento e Capacitação da Equipe', 'Fortalecer a comunicação e aumentar a motivação e produtividade através de programas de capacitação e alinhamento interno.', 'planejamento', 'media', '2025-12-27', NULL, 1, '2025-12-27 09:41:18', '2025-12-27 09:41:18'),
(29, 49, 'Estratégia de Aquisição e Jornada do Cliente', 'Reformular as estratégias de aquisição com segmentação avançada e aprimorar a experiência do cliente para aumentar conversões e fidelização.', 'planejamento', 'alta', '2025-12-27', NULL, 1, '2025-12-27 09:41:24', '2025-12-27 09:41:24'),
(30, 51, 'Automatização Financeira e Controle', 'Reduzir erros, aumentar a precisão no fluxo de caixa e a previsibilidade financeira por meio da automação e implementação de governança financeira.', 'planejamento', 'alta', '2025-12-27', NULL, 1, '2025-12-27 17:49:23', '2025-12-27 17:49:23'),
(31, 51, 'Automatização Financeira e Controle', 'Reduzir erros, aumentar a precisão no fluxo de caixa e a previsibilidade financeira por meio da automação e implementação de governança financeira.', 'planejamento', 'alta', '2025-12-27', NULL, 1, '2025-12-27 18:07:04', '2025-12-27 18:07:04'),
(32, NULL, 'ASDA', 'A', 'planejamento', 'media', '2025-12-27', NULL, 1, '2025-12-27 18:21:16', '2025-12-27 18:21:16'),
(33, 52, 'Automatização e Integração Operacional', 'Melhorar a eficiência operacional reduzindo tarefas manuais e integrando sistemas para garantir maior agilidade e controle dos processos internos.', 'planejamento', 'alta', '2025-12-27', NULL, 1, '2025-12-27 19:43:11', '2025-12-27 19:43:11'),
(36, NULL, 'Desenvolvimento Novo Site Clínica', '**OBJETIVO:** Criar um novo site moderno, funcional e responsivo para a clínica, visando melhorar a experiência do usuário e aumentar a captação de pacientes.\n\n**ESCOPO:** Desenvolver design, conteúdo, funcionalidades (agendamento online, área do paciente, blog), integração com sistemas internos e testes para garantir usabilidade e performance.\n\n**ENTREGÁVEIS:**\n- Protótipo visual aprovado\n- Site responsivo implementado\n- Sistema de agendamento integrado\n- Área de conteúdo para blog\n- Testes de usabilidade e performance concluídos', 'planejamento', 'alta', '2025-12-27', NULL, 1, '2025-12-27 20:03:21', '2025-12-27 20:03:21'),
(37, NULL, 'Projeto de Expansão Comercial 2025', '**OBJETIVO:** Expandir a presença comercial da empresa em novos mercados e aumentar a receita anual em 2025.\n\n**ESCOPO:** Realizar pesquisas de mercado, identificar novas regiões estratégicas para atuação, desenvolver novos canais de venda e fortalecer parcerias comerciais existentes.\n\n**ENTREGÁVEIS:**\n- Relatório de análise de mercados potenciais\n- Plano de entrada para novas regiões\n- Estratégia de canais de venda\n- Parcerias comerciais formalizadas e documentadas\n- Metas de crescimento comercial definidas e compartilhadas', 'planejamento', 'alta', '2025-12-27', NULL, 1, '2025-12-27 20:31:52', '2025-12-27 20:31:52'),
(38, NULL, 'Projeto de Expansão Comercial 2025', '**OBJETIVO:**\n- Expandir a presença comercial da empresa em novos mercados durante o ano de 2025, aumentando receita e participação de mercado.\n\n**ESCOPO:**\n- Identificação e análise de mercados-alvo potenciais;\n- Desenvolvimento e execução de estratégias de penetração;\n- Ampliação da rede de vendas e canais de distribuição;\n- Monitoramento e ajuste contínuo das ações para garantir resultados.\n\n**MARCOS:**\n- Conclusão da análise de mercados-alvo: 31/01/2025\n- Lançamento das primeiras operações nos novos mercados: 30/06/2025\n- Avaliação intermediária de performance comercial: 30/09/2025\n- Finalização do plano de expansão e primeira rodada de ajustes: 31/12/2025', 'planejamento', 'alta', '2025-12-27', NULL, 1, '2025-12-27 20:35:09', '2025-12-27 20:35:09'),
(39, NULL, 'Estruturação do Processo Comercial da Clínica', '**OBJETIVO**: Desenvolver e implementar um processo comercial eficiente e padronizado para a clínica, visando aumentar a captação e fidelização de pacientes, além de melhorar a gestão dos atendimentos e do fluxo comercial.\n\n**ESCOPO**:\n- Mapeamento do processo comercial atual\n- Análise dos pontos de melhoria\n- Definição de etapas padrão do processo comercial (prospecção, atendimento, negociação, fechamento e pós-venda)\n- Implementação de ferramentas e indicadores comerciais\n- Treinamento da equipe comercial e de atendimento\n\n**MARCOS**:\n- Conclusão do mapeamento e diagnóstico do processo atual\n- Definição e validação do novo fluxo comercial\n- Implantação das ferramentas de suporte\n- Treinamento das equipes\n- Avaliação inicial dos resultados após 3 meses de operação', 'planejamento', 'alta', '2025-12-27', NULL, 1, '2025-12-27 20:40:27', '2025-12-27 20:40:27'),
(40, NULL, 'teste', '', 'planejamento', 'media', '2025-12-27', NULL, 1, '2025-12-27 20:40:50', '2025-12-27 20:40:50');

