--
-- Estrutura para tabela `gestao_tarefas`
--

CREATE TABLE `gestao_tarefas` (
  `id` int(11) NOT NULL,
  `titulo` varchar(255) NOT NULL,
  `descricao` text DEFAULT NULL,
  `status` enum('todo','doing','done') DEFAULT 'todo',
  `prioridade` enum('baixa','media','alta') DEFAULT 'media',
  `data_criacao` datetime DEFAULT current_timestamp(),
  `data_conclusao` datetime DEFAULT NULL,
  `ordem` int(11) DEFAULT 0,
  `projeto_id` int(11) DEFAULT NULL,
  `prazo` datetime DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

--
-- Despejando dados para a tabela `gestao_tarefas`
--

INSERT INTO `gestao_tarefas` (`id`, `titulo`, `descricao`, `status`, `prioridade`, `data_criacao`, `data_conclusao`, `ordem`, `projeto_id`, `prazo`) VALUES
(118, 'Mapear processos operacionais críticos', '**O que é:** Identificar e documentar os processos mais relevantes.\n\n**Passo a Passo:**\n1. Reunir equipe operacional para levantamento dos processos.\n2. Documentar fluxos em formato padrão.\n\n**Resultado Esperado:** Processos críticos mapeados e disponíveis para análise.', 'todo', 'alta', '2025-12-27 05:55:09', NULL, 0, 18, '2024-07-15 00:00:00'),
(119, 'Selecionar ferramenta de automação adequada', '**O que é:** Escolher software que suporte automação dos processos mapeados.\n\n**Passo a Passo:**\n1. Levantar opções no mercado.\n2. Avaliar custo-benefício e compatibilidade.\n3. Apresentar recomendação à diretoria.\n\n**Resultado Esperado:** Ferramenta definida para implementação.', 'todo', 'alta', '2025-12-27 05:55:09', NULL, 0, 18, '2024-07-31 00:00:00'),
(120, 'Treinar equipe para utilização da ferramenta', '**O que é:** Capacitar colaboradores para operar a nova plataforma.\n\n**Passo a Passo:**\n1. Agendar treinamentos presenciais e online.\n2. Desenvolver material de apoio.\n3. Realizar sessões práticas.\n\n**Resultado Esperado:** Equipe habilitada para uso eficiente da ferramenta.', 'todo', 'alta', '2025-12-27 05:55:09', NULL, 0, 18, '2024-08-15 00:00:00'),
(121, 'Implementar automação nos processos prioritários', '**O que é:** Configurar e rodar automação para principais tarefas mapeadas.\n\n**Passo a Passo:**\n1. Ajustar configurações da ferramenta.\n2. Executar testes-piloto.\n3. Validar resultados com equipe.\n\n**Resultado Esperado:** Processos automáticos funcionando e monitorados.', 'todo', 'alta', '2025-12-27 05:55:09', NULL, 0, 18, '2024-09-30 00:00:00'),
(122, 'Monitorar e otimizar processos automatizados', '**O que é:** Avaliar desempenho contínuo e promover melhorias.\n\n**Passo a Passo:**\n1. Definir indicadores de eficiência.\n2. Coletar dados de uso semanalmente.\n3. Ajustar processos quando necessário.\n\n**Resultado Esperado:** Processos otimizados e controlados por KPIs.', 'todo', 'alta', '2025-12-27 05:55:09', NULL, 0, 18, '2024-10-31 00:00:00'),
(123, 'Diagnosticar atuais processos financeiros e de aquisição', '**O que é:** Levantar práticas, falhas e oportunidades existentes.\n\n**Passo a Passo:**\n1. Entrevistar gestores financeiros e responsáveis por compras.\n2. Revisar documentação e contratos.\n\n**Resultado Esperado:** Relatório de diagnóstico completo.', 'todo', 'media', '2025-12-27 05:55:12', NULL, 0, 19, '2024-07-20 00:00:00'),
(124, 'Definir critérios para seleção e avaliação de fornecedores', '**O que é:** Criar parâmetros para compras eficientes e seguras.\n\n**Passo a Passo:**\n1. Analisar necessidades internas.\n2. Definir indicadores de desempenho e compliance.\n3. Formalizar critérios em documento.\n\n**Resultado Esperado:** Critérios claros para avaliação de fornecedores.', 'todo', 'media', '2025-12-27 05:55:12', NULL, 0, 19, '2024-08-10 00:00:00'),
(125, 'Implementar sistema integrado de controle financeiro', '**O que é:** Adotar plataforma que centralize e automatize finanças e aquisições.\n\n**Passo a Passo:**\n1. Selecionar sistema conforme necessidade.\n2. Configurar base de dados e integrações.\n3. Treinar equipe para uso.\n\n**Resultado Esperado:** Sistema implantado e funcional.', 'todo', 'media', '2025-12-27 05:55:12', NULL, 0, 19, '2024-09-30 00:00:00'),
(126, 'Cadastrar e qualificar fornecedores', '**O que é:** Formalizar cadastro para uso transparente e seguro nas compras.\n\n**Passo a Passo:**\n1. Solicitar informações e documentação dos fornecedores atuais.\n2. Avaliar conforme critérios estabelecidos.\n3. Atualizar banco de dados.\n\n**Resultado Esperado:** Base de fornecedores qualificada e atualizada.', 'todo', 'media', '2025-12-27 05:55:12', NULL, 0, 19, '2024-10-31 00:00:00'),
(127, 'Monitorar indicadores financeiros e de aquisição', '**O que é:** Estabelecer acompanhamento e ajustes constantes.\n\n**Passo a Passo:**\n1. Definir KPIs financeiros e indicadores de compra.\n2. Realizar reuniões mensais de análise.\n3. Implementar melhorias conforme resultado.\n\n**Resultado Esperado:** Controle efetivo e contínuo das finanças e aquisições.', 'todo', 'media', '2025-12-27 05:55:12', NULL, 0, 19, '2024-11-30 00:00:00'),
(128, 'Realizar diagnóstico de competências e necessidades da equipe', '**O que é:** Identificar gaps de habilidades e áreas de melhoria.\n\n**Passo a Passo:**\n1. Aplicar levantamento de competências atuais.\n2. Analisar necessidades estratégicas.\n\n**Resultado Esperado:** Mapa de competências e gaps para plano de ação.', 'todo', 'media', '2025-12-27 05:55:13', NULL, 0, 20, '2024-07-25 00:00:00'),
(129, 'Desenvolver programa de capacitação contínua', '**O que é:** Estruturar treinamentos que aumentem o conhecimento técnico e comportamental.\n\n**Passo a Passo:**\n1. Selecionar temas prioritários.\n2. Planejar agenda e formato dos treinamentos.\n3. Preparar materiais e instrutores.\n\n**Resultado Esperado:** Programa estruturado e divulgado para equipe.', 'todo', 'media', '2025-12-27 05:55:13', NULL, 0, 20, '2024-08-20 00:00:00'),
(130, 'Implementar sistema de avaliação de desempenho', '**O que é:** Criar processo formal para feedback e desenvolvimento.\n\n**Passo a Passo:**\n1. Definir critérios e métricas de avaliação.\n2. Comunicar processo para equipe.\n3. Realizar avaliações piloto.\n\n**Resultado Esperado:** Processo de avaliação funcional e aceito.', 'todo', 'media', '2025-12-27 05:55:13', NULL, 0, 20, '2024-09-30 00:00:00'),
(131, 'Promover sessões de feedback e coaching', '**O que é:** Estimular melhoria contínua e engajamento.\n\n**Passo a Passo:**\n1. Agendar reuniões individuais.\n2. Treinar líderes em técnicas de feedback.\n3. Documentar e acompanhar evolução.\n\n**Resultado Esperado:** Maior engajamento e desenvolvimento individual.', 'todo', 'media', '2025-12-27 05:55:13', NULL, 0, 20, '2024-10-31 00:00:00'),
(132, 'Monitorar indicadores de engajamento e turnover', '**O que é:** Avaliar resultados e ajustar ações.\n\n**Passo a Passo:**\n1. Definir métricas e métodos de pesquisa.\n2. Aplicar pesquisas periódicas.\n3. Analisar resultados e sugerir melhorias.\n\n**Resultado Esperado:** Redução de turnover e maior satisfação.', 'todo', 'media', '2025-12-27 05:55:13', NULL, 0, 20, '2024-12-31 00:00:00'),
(133, 'Mapear processos atuais', '**O que é:** Levantar detalhamento dos processos operacionais existentes.\n\n**Passo a Passo:**\n1. Reunir equipe operacional para mapear etapas.\n2. Documentar cada processo em fluxogramas.\n\n**Resultado Esperado:** Mapa completo dos processos atuais com pontos críticos identificados.', 'todo', 'alta', '2025-12-27 06:00:30', NULL, 0, 21, '2024-07-10 00:00:00'),
(134, 'Avaliar soluções de automação', '**O que é:** Pesquisar e comparar ferramentas de automação compatíveis.\n\n**Passo a Passo:**\n1. Listar soluções disponíveis no mercado.\n2. Analisar funcionalidades e custos.\n3. Selecionar as 3 melhores opções.\n\n**Resultado Esperado:** Documento comparativo com recomendação da melhor ferramenta.', 'todo', 'alta', '2025-12-27 06:00:30', NULL, 0, 21, '2024-07-25 00:00:00'),
(135, 'Desenvolver plano de implementação', '**O que é:** Elaborar roteiro para aplicar a automação nos processos prioritários.\n\n**Passo a Passo:**\n1. Priorizar processos para automação.\n2. Definir cronograma e responsabilidades.\n\n**Resultado Esperado:** Plano formal de implantação estruturado.', 'todo', 'alta', '2025-12-27 06:00:30', NULL, 0, 21, '2024-08-05 00:00:00'),
(136, 'Treinar equipe operacional', '**O que é:** Capacitar colaboradores para operar com as novas ferramentas.\n\n**Passo a Passo:**\n1. Criar material de treinamento.\n2. Realizar workshops práticos.\n\n**Resultado Esperado:** Equipe apta a utilizar sistemas automatizados.', 'todo', 'alta', '2025-12-27 06:00:30', NULL, 0, 21, '2024-08-20 00:00:00'),
(137, 'Executar pilotos de automação', '**O que é:** Implantar automação em processos selecionados em fase teste.\n\n**Passo a Passo:**\n1. Configurar sistema para processos-piloto.\n2. Monitorar e coletar feedback.\n\n**Resultado Esperado:** Validação operacional dos processos automatizados.', 'todo', 'alta', '2025-12-27 06:00:30', NULL, 0, 21, '2024-09-15 00:00:00'),
(138, 'Avaliar resultados e ajustar', '**O que é:** Analisar desempenho dos processos automatizados e realizar melhorias.\n\n**Passo a Passo:**\n1. Comparar indicadores antes e depois da automação.\n2. Implementar ajustes necessários.\n\n**Resultado Esperado:** Processos otimizados com ganhos claros de eficiência.', 'todo', 'alta', '2025-12-27 06:00:30', NULL, 0, 21, '2024-10-30 00:00:00'),
(139, 'Diagnosticar sistemas e controles atuais', '**O que é:** Avaliar ferramentas e processos usados para gestão financeira.\n\n**Passo a Passo:**\n1. Levantar relatórios usados.\n2. Identificar falhas e inconsistências.\n\n**Resultado Esperado:** Relatório das fragilidades atuais em controle financeiro.', 'todo', 'media', '2025-12-27 06:00:30', NULL, 0, 22, '2024-07-15 00:00:00'),
(140, 'Definir indicadores financeiros chave', '**O que é:** Selecionar KPIs essenciais para acompanhar saúde financeira.\n\n**Passo a Passo:**\n1. Revisar objetivos financeiros estratégicos.\n2. Escolher métricas relevantes para operação.\n\n**Resultado Esperado:** Lista de KPIs financeiros a monitorar regularmente.', 'todo', 'media', '2025-12-27 06:00:30', NULL, 0, 22, '2024-07-25 00:00:00'),
(141, 'Implementar dashboard financeiro', '**O que é:** Criar painel visual de acompanhamento dos KPIs definidos.\n\n**Passo a Passo:**\n1. Escolher software para dashboard.\n2. Integrar dados contábeis e operacionais.\n\n**Resultado Esperado:** Dashboard ativo com dados atualizados automaticamente.', 'todo', 'media', '2025-12-27 06:00:30', NULL, 0, 22, '2024-08-30 00:00:00'),
(142, 'Desenvolver planejamento financeiro trimestral', '**O que é:** Planejar receitas, despesas e investimentos para trimestre.\n\n**Passo a Passo:**\n1. Coletar dados históricos.\n2. Projetar cenário futuro e orçamento.\n\n**Resultado Esperado:** Documento formal de planejamento financeiro aprovado.', 'todo', 'media', '2025-12-27 06:00:30', NULL, 0, 22, '2024-09-30 00:00:00'),
(143, 'Treinar equipe financeira', '**O que é:** Habilitar equipe para uso dos novos controles e interpretações de dados.\n\n**Passo a Passo:**\n1. Preparar material de treinamento.\n2. Realizar capacitação presencial ou online.\n\n**Resultado Esperado:** Equipe apta a operar o sistema e interpretar relatórios.', 'todo', 'media', '2025-12-27 06:00:30', NULL, 0, 22, '2024-10-10 00:00:00'),
(144, 'Mapear canais atuais de aquisição', '**O que é:** Identificar e analisar todos os canais usados para captar clientes.\n\n**Passo a Passo:**\n1. Listar canais ativos.\n2. Medir desempenho histórico.\n\n**Resultado Esperado:** Documento com análise quantitativa e qualitativa dos canais.', 'todo', 'alta', '2025-12-27 06:00:31', NULL, 0, 23, '2024-07-10 00:00:00'),
(145, 'Definir canais prioritários para investimento', '**O que é:** Selecionar os 3 canais mais promissores para focar recursos.\n\n**Passo a Passo:**\n1. Avaliar custo-benefício de cada canal.\n2. Considerar público-alvo e potencial de escala.\n\n**Resultado Esperado:** Lista validada dos canais prioritários para aquisição.', 'todo', 'alta', '2025-12-27 06:00:31', NULL, 0, 23, '2024-07-20 00:00:00'),
(146, 'Estabelecer funil de conversão estruturado', '**O que é:** Criar etapas claras da jornada do cliente, com métricas em cada fase.\n\n**Passo a Passo:**\n1. Definir etapas desde lead até fechamento.\n2. Implantar ferramenta para monitoramento.\n\n**Resultado Esperado:** Funil de vendas operando com indicadores visíveis.', 'todo', 'alta', '2025-12-27 06:00:31', NULL, 0, 23, '2024-08-15 00:00:00'),
(147, 'Criar campanhas para canais selecionados', '**O que é:** Planejar e executar ações direcionadas nos canais priorizados.\n\n**Passo a Passo:**\n1. Desenvolver conteúdo e ofertas específicas.\n2. Lançar campanhas e monitorar resultados.\n\n**Resultado Esperado:** Campanhas ativas gerando leads qualificados.', 'todo', 'alta', '2025-12-27 06:00:31', NULL, 0, 23, '2024-09-05 00:00:00'),
(148, 'Monitorar e otimizar taxa de conversão', '**O que é:** Avaliar desempenho e promover melhorias no funil.\n\n**Passo a Passo:**\n1. Analisar dados semanalmente.\n2. Ajustar abordagens e mensagens.\n\n**Resultado Esperado:** Incremento contínuo da taxa de conversão.', 'todo', 'alta', '2025-12-27 06:00:31', NULL, 0, 23, '2024-12-31 00:00:00'),
(149, 'Mapear processos atuais', '**O que é:** Levantamento detalhado dos processos operacionais e financeiros atuais.\n\n**Passo a Passo:**\n1. Realizar entrevistas com operadores e gestores.\n2. Documentar fluxos e documentos utilizados.\n\n**Resultado Esperado:** Documento com fluxo atual dos processos levantados.', 'todo', 'alta', '2025-12-27 06:32:00', NULL, 0, 24, '2024-07-10 00:00:00'),
(150, 'Selecionar ferramentas de automação', '**O que é:** Pesquisa e escolha de sistemas que suportem automação e integração.\n\n**Passo a Passo:**\n1. Listar necessidades dos processos.\n2. Pesquisar fornecedores e realizar testes.\n3. Escolher ferramentas adequadas.\n\n**Resultado Esperado:** Relatório de recomendações com ferramentas selecionadas.', 'todo', 'alta', '2025-12-27 06:32:00', NULL, 0, 24, '2024-07-20 00:00:00'),
(151, 'Desenvolver integração entre sistemas', '**O que é:** Construção das integrações necessárias entre os sistemas para fluxo contínuo.\n\n**Passo a Passo:**\n1. Definir APIs e métodos de integração.\n2. Programar e testar conexões.\n\n**Resultado Esperado:** Sistemas integrados funcionando sem intervenções manuais.', 'todo', 'alta', '2025-12-27 06:32:00', NULL, 0, 24, '2024-08-30 00:00:00'),
(152, 'Treinar equipe em novos sistemas', '**O que é:** Capacitação para que a equipe opere com as novas ferramentas.\n\n**Passo a Passo:**\n1. Preparar manual e materiais de treinamento.\n2. Agendar sessões de treinamento.\n3. Executar treinamentos com feedback.\n\n**Resultado Esperado:** Equipe apta a operar as novas rotinas digitais.', 'todo', 'alta', '2025-12-27 06:32:00', NULL, 0, 24, '2024-09-10 00:00:00'),
(153, 'Monitorar automatização e ajustar processos', '**O que é:** Avaliação contínua da automação para corrigir falhas e otimizar.\n\n**Passo a Passo:**\n1. Definir indicadores de desempenho.\n2. Realizar acompanhamentos periódicos.\n3. Ajustar processos conforme necessidade.\n\n**Resultado Esperado:** Automação estável e eficiente, com melhoria contínua.', 'todo', 'alta', '2025-12-27 06:32:00', NULL, 0, 24, '2024-10-31 00:00:00'),
(154, 'Analisar dados atuais de aquisição', '**O que é:** Estudo dos dados históricos para identificar pontos fortes e falhas.\n\n**Passo a Passo:**\n1. Coletar dados de canais e vendas.\n2. Analisar perfil dos clientes adquiridos.\n\n**Resultado Esperado:** Relatório com diagnóstico profundo da aquisição atual.', 'doing', 'alta', '2025-12-27 06:32:00', NULL, 0, 25, '2024-07-05 00:00:00'),
(155, 'Mapear canais potenciais novos', '**O que é:** Pesquisa de oportunidades em canais alternativos de aquisição.\n\n**Passo a Passo:**\n1. Estudar canais digitais, parcerias e eventos.\n2. Avaliar custo-benefício de cada canal.\n\n**Resultado Esperado:** Lista qualificada de canais para testar.', 'todo', 'alta', '2025-12-27 06:32:00', NULL, 0, 25, '2024-07-15 00:00:00'),
(156, 'Desenvolver campanhas piloto', '**O que é:** Criar campanhas para os canais novos visando avaliação de performance.\n\n**Passo a Passo:**\n1. Definir objetivos e públicos-alvo.\n2. Criar peças e mensagens.\n3. Executar campanhas em pequenos grupos.\n\n**Resultado Esperado:** Dados de performance para decisão de escalonamento.', 'todo', 'alta', '2025-12-27 06:32:00', NULL, 0, 25, '2024-08-15 00:00:00'),
(157, 'Ajustar funil de vendas e processos de conversão', '**O que é:** Otimizar etapas de acompanhamento e entrega para melhorar taxa de conversão.\n\n**Passo a Passo:**\n1. Analisar mapa da jornada.\n2. Definir melhorias para objeções e follow-up.\n3. Implementar ajustes.\n\n**Resultado Esperado:** Funil mais eficiente com melhores taxas de conversão.', 'todo', 'alta', '2025-12-27 06:32:00', NULL, 0, 25, '2024-09-15 00:00:00'),
(158, 'Coletar feedbacks e reclamações dos clientes', '**O que é:** Levantar dados qualitativos e quantitativos de experiências reais.\n\n**Passo a Passo:**\n1. Aplicar pesquisas pós-venda e atendimento.\n2. Consolidar dados em banco único.\n\n**Resultado Esperado:** Relatório com insights dos pontos de dor e satisfação.', 'todo', 'media', '2025-12-27 06:32:01', NULL, 0, 26, '2024-07-10 00:00:00'),
(159, 'Mapear todos os pontos de contato', '**O que é:** Documentar cada etapa da interação do cliente com a empresa.\n\n**Passo a Passo:**\n1. Identificar canais e momentos de contato.\n2. Criar mapa visual da jornada.\n\n**Resultado Esperado:** Mapa visual detalhado da jornada do cliente.', 'todo', 'media', '2025-12-27 06:32:01', NULL, 0, 26, '2024-07-31 00:00:00'),
(160, 'Analisar gargalos e oportunidades', '**O que é:** Avaliar o mapa e feedbacks para priorizar melhorias.\n\n**Passo a Passo:**\n1. Cruzar dados qualitativos e quantitativos.\n2. Listar prioridades de melhoria.\n\n**Resultado Esperado:** Plano de ação focado nas principais dores do cliente.', 'todo', 'media', '2025-12-27 06:32:01', NULL, 0, 26, '2024-08-10 00:00:00'),
(161, 'Implementar melhorias de experiência', '**O que é:** Aplicar mudanças que aumentem satisfação e engajamento.\n\n**Passo a Passo:**\n1. Desenvolver melhorias táticas.\n2. Executar pilotos e monitorar resultados.\n\n**Resultado Esperado:** Melhoria prática e mensurável na jornada do cliente.', 'todo', 'media', '2025-12-27 06:32:01', NULL, 0, 26, '2024-09-30 00:00:00'),
(162, 'Capacitar equipe para atendimento focado na jornada', '**O que é:** Treinamento para atendimento alinhado ao mapeamento da jornada.\n\n**Passo a Passo:**\n1. Criar conteúdo de treinamento.\n2. Realizar sessões práticas.\n\n**Resultado Esperado:** Equipe apta a entregar excelência a cada ponto de contato.', 'todo', 'media', '2025-12-27 06:32:01', NULL, 0, 26, '2024-09-30 00:00:00'),
(163, 'Mapear processos operacionais manuais', '**O que é:** Levantar todos os processos que ainda dependem de ações manuais.\n\n**Passo a Passo:**\n1. Reunir equipe operacional para identificar processos.\n2. Documentar processos, destacando atividades repetitivas.\n\n**Resultado Esperado:** Lista detalhada dos processos manuais para priorização.', 'doing', 'alta', '2025-12-27 06:41:16', NULL, 0, 27, '2024-07-05 00:00:00'),
(164, 'Selecionar ferramentas de automação', '**O que é:** Avaliar soluções tecnológicas para automação dos processos identificados.\n\n**Passo a Passo:**\n1. Pesquisa de mercado e análise de ferramentas.\n2. Demonstrar opções para stakeholders.\n\n**Resultado Esperado:** Escolha da plataforma ideal para automação operacional.', 'todo', 'alta', '2025-12-27 06:41:16', NULL, 0, 27, '2024-07-15 00:00:00'),
(165, 'Desenvolver fluxos automatizados', '**O que é:** Criar e testar automações baseadas nos processos selecionados.\n\n**Passo a Passo:**\n1. Configurar scripts e integrações.\n2. Realizar testes piloto.\n\n**Resultado Esperado:** Automação funcional em ambiente de teste.', 'todo', 'alta', '2025-12-27 06:41:16', NULL, 0, 27, '2024-08-10 00:00:00'),
(166, 'Treinar equipe na nova ferramenta', '**O que é:** Capacitar os colaboradores para utilização da automação.\n\n**Passo a Passo:**\n1. Preparar material didático.\n2. Realizar oficinas práticas.\n\n**Resultado Esperado:** Equipe apta a operar o sistema automatizado.', 'todo', 'alta', '2025-12-27 06:41:16', NULL, 0, 27, '2024-08-20 00:00:00'),
(167, 'Implementar automação em produção', '**O que é:** Migrar processos para o ambiente real garantindo estabilidade.\n\n**Passo a Passo:**\n1. Planejar rollout gradual.\n2. Monitorar indicadores e corrigir falhas.\n\n**Resultado Esperado:** Procura automatizada e estável em operação.', 'todo', 'alta', '2025-12-27 06:41:16', NULL, 0, 27, '2024-09-05 00:00:00'),
(168, 'Diagnosticar comunicação interna', '**O que é:** Avaliar os canais atuais e identificar falhas.\n\n**Passo a Passo:**\n1. Aplicar pesquisa com colaboradores.\n2. Analisar resultados e canais existentes.\n\n**Resultado Esperado:** Relatório com gaps de comunicação interna.', 'todo', 'media', '2025-12-27 06:41:18', NULL, 0, 28, '2024-07-10 00:00:00'),
(169, 'Desenvolver plano de comunicação interna', '**O que é:** Criar estratégias para melhorar o fluxo e clareza das informações.\n\n**Passo a Passo:**\n1. Planejar reuniões periódicas e canais oficiais.\n2. Definir responsáveis pela comunicação.\n\n**Resultado Esperado:** Plano documentado e aprovado pela liderança.', 'todo', 'media', '2025-12-27 06:41:18', NULL, 0, 28, '2024-07-25 00:00:00'),
(170, 'Planejar programa de capacitação e treinamentos', '**O que é:** Preparar conteúdos para desenvolver habilidades críticas da equipe.\n\n**Passo a Passo:**\n1. Identificar necessidades via avaliação de desempenho.\n2. Criação e agendamento de treinamentos.\n\n**Resultado Esperado:** Calendário de treinamentos homologado.', 'todo', 'media', '2025-12-27 06:41:18', NULL, 0, 28, '2024-08-05 00:00:00'),
(171, 'Realizar treinamentos práticos', '**O que é:** Promover capacitações focadas em processos e soft skills.\n\n**Passo a Passo:**\n1. Conduzir sessões presenciais ou online.\n2. Aplicar avaliação para medir aprendizado.\n\n**Resultado Esperado:** Colaboradores treinados e feedback positivo.', 'todo', 'media', '2025-12-27 06:41:18', NULL, 0, 28, '2024-08-30 00:00:00'),
(172, 'Monitorar resultados e ajustar ações', '**O que é:** Avaliar impacto dos treinamentos e comunicação com métricas.\n\n**Passo a Passo:**\n1. Acompanhar indicadores de produtividade e clima.\n2. Realizar reuniões de ajuste com equipe.\n\n**Resultado Esperado:** Plano de continuidade ajustado conforme resultados.', 'todo', 'media', '2025-12-27 06:41:18', NULL, 0, 28, '2024-09-15 00:00:00'),
(173, 'Analisar perfil dos clientes atuais', '**O que é:** Entender melhor quem são os clientes para segmentar campanhas.\n\n**Passo a Passo:**\n1. Coletar dados e feedbacks.\n2. Criar personas detalhadas.\n\n**Resultado Esperado:** Base de personas para direcionamento das ações.', 'doing', 'alta', '2025-12-27 06:41:24', NULL, 0, 29, '2024-07-03 00:00:00'),
(174, 'Desenvolver campanhas segmentadas', '**O que é:** Criar campanhas centradas nas personas definidas.\n\n**Passo a Passo:**\n1. Planejar conteúdos e ofertas customizadas.\n2. Implementar campanhas multi-canais.\n\n**Resultado Esperado:** Campanhas lançadas com mensagens personalizadas.', 'todo', 'alta', '2025-12-27 06:41:24', NULL, 0, 29, '2024-07-25 00:00:00'),
(175, 'Mapear jornada do cliente atual', '**O que é:** Identificar todos os pontos de contato e experiências atuais dos clientes.\n\n**Passo a Passo:**\n1. Levantar processos de onboarding e pós-venda.\n2. Detectar gargalos e oportunidades.\n\n**Resultado Esperado:** Mapa visual da jornada com áreas de melhoria.', 'todo', 'alta', '2025-12-27 06:41:24', NULL, 0, 29, '2024-07-15 00:00:00'),
(176, 'Implementar ações de fidelização', '**O que é:** Desenvolver programas para aumentar engajamento e retenção.\n\n**Passo a Passo:**\n1. Criar planos de comunicação e ofertas exclusivas.\n2. Monitorar satisfação e ajustar plano.\n\n**Resultado Esperado:** Programa ativo com indicadores de retenção positivos.', 'todo', 'alta', '2025-12-27 06:41:24', NULL, 0, 29, '2024-08-20 00:00:00'),
(177, 'Integrar feedbacks para melhoria contínua', '**O que é:** Estabelecer rotina para coleta e implementação dos feedbacks dos clientes.\n\n**Passo a Passo:**\n1. Criar canais de comunicação direta.\n2. Analisar dados e executar ações corretivas.\n\n**Resultado Esperado:** Ciclo de melhoria contínua implantado na jornada do cliente.', 'todo', 'alta', '2025-12-27 06:41:24', NULL, 0, 29, '2024-08-30 00:00:00'),
(178, 'Mapear processos financeiros atuais', '**O que é:** Levantar e documentar todos os processos financeiros existentes.\n\n**Passo a Passo:**\n1. Entrevistar equipe financeira.\n2. Identificar pontos manuais e principais gargalos.\n\n**Resultado Esperado:** Documento com mapeamento completo dos processos financeiros.\n', 'todo', 'alta', '2025-12-27 14:49:23', NULL, 0, 30, '2024-07-10 00:00:00'),
(179, 'Selecionar ferramenta de automação financeira', '**O que é:** Avaliar e escolher software ideal para automatizar processos financeiros.\n\n**Passo a Passo:**\n1. Levantar requisitos.\n2. Fazer demonstrações e análise custo-benefício.\n3. Definir ferramenta.\n\n**Resultado Esperado:** Escolha da ferramenta para automação financeira.\n', 'todo', 'alta', '2025-12-27 14:49:23', NULL, 0, 30, '2024-07-17 00:00:00'),
(180, 'Treinar equipe na ferramenta escolhida', '**O que é:** Capacitar time financeiro para utilização plena da nova solução.\n\n**Passo a Passo:**\n1. Preparar material de treinamento.\n2. Realizar workshops práticos.\n\n**Resultado Esperado:** Equipe apta a utilizar a ferramenta com autonomia.\n', 'todo', 'alta', '2025-12-27 14:49:23', NULL, 0, 30, '2024-07-31 00:00:00'),
(181, 'Implementar controle e monitoramento de fluxo de caixa', '**O que é:** Estruturar controle diário e semanal do fluxo de caixa.\n\n**Passo a Passo:**\n1. Definir indicadores e dashboards.\n2. Automatizar geração e envio de relatórios.\n\n**Resultado Esperado:** Fluxo de caixa monitorado em tempo real e relatórios acessíveis.\n', 'todo', 'alta', '2025-12-27 14:49:23', NULL, 0, 30, '2024-08-15 00:00:00'),
(182, 'Documentar políticas e governança financeira', '**O que é:** Criar normas para regular processos e responsabilidades financeiras.\n\n**Passo a Passo:**\n1. Definir regras internas.\n2. Validar com liderança.\n3. Divulgar e treinar time.\n\n**Resultado Esperado:** Manual de governança financeira institucionalizado.\n', 'todo', 'alta', '2025-12-27 14:49:23', NULL, 0, 30, '2024-08-20 00:00:00'),
(183, 'Mapear processos financeiros atuais', '**O que é:** Levantar e documentar todos os processos financeiros existentes.\n\n**Passo a Passo:**\n1. Entrevistar equipe financeira.\n2. Identificar pontos manuais e principais gargalos.\n\n**Resultado Esperado:** Documento com mapeamento completo dos processos financeiros.\n', 'todo', 'alta', '2025-12-27 15:07:04', NULL, 0, 31, '2024-07-10 00:00:00'),
(184, 'Selecionar ferramenta de automação financeira', '**O que é:** Avaliar e escolher software ideal para automatizar processos financeiros.\n\n**Passo a Passo:**\n1. Levantar requisitos.\n2. Fazer demonstrações e análise custo-benefício.\n3. Definir ferramenta.\n\n**Resultado Esperado:** Escolha da ferramenta para automação financeira.\n', 'todo', 'alta', '2025-12-27 15:07:04', NULL, 0, 31, '2024-07-17 00:00:00'),
(185, 'Treinar equipe na ferramenta escolhida', '**O que é:** Capacitar time financeiro para utilização plena da nova solução.\n\n**Passo a Passo:**\n1. Preparar material de treinamento.\n2. Realizar workshops práticos.\n\n**Resultado Esperado:** Equipe apta a utilizar a ferramenta com autonomia.\n', 'todo', 'alta', '2025-12-27 15:07:04', NULL, 0, 31, '2024-07-31 00:00:00'),
(186, 'Implementar controle e monitoramento de fluxo de caixa', '**O que é:** Estruturar controle diário e semanal do fluxo de caixa.\n\n**Passo a Passo:**\n1. Definir indicadores e dashboards.\n2. Automatizar geração e envio de relatórios.\n\n**Resultado Esperado:** Fluxo de caixa monitorado em tempo real e relatórios acessíveis.\n', 'todo', 'alta', '2025-12-27 15:07:04', NULL, 0, 31, '2024-08-15 00:00:00'),
(187, 'Documentar políticas e governança financeira', '**O que é:** Criar normas para regular processos e responsabilidades financeiras.\n\n**Passo a Passo:**\n1. Definir regras internas.\n2. Validar com liderança.\n3. Divulgar e treinar time.\n\n**Resultado Esperado:** Manual de governança financeira institucionalizado.\n', 'todo', 'alta', '2025-12-27 15:07:04', NULL, 0, 31, '2024-08-20 00:00:00'),
(190, 'Analisar Relatório de DRE', '**O QUE É:**\r\nAnálise detalhada do Demonstrativo de Resultados do Exercício (DRE) para entender a saúde financeira da empresa, identificar pontos de melhoria e tomar decisões fundamentadas.\r\n\r\n**PASSOS SUGERIDOS:**\r\n- Organizar e revisar os dados financeiros do relatório de DRE, garantindo que estejam completos e corretos.\r\n- Comparar receitas, despesas, lucro bruto, despesas operacionais e lucro líquido com períodos anteriores ou metas estabelecidas.\r\n- Identificar variações relevantes, entender causas e destacar oportunidades ou riscos para a gestão.\r\n\r\n**RESULTADO ESPERADO:**\r\nRelatório detalhado com insights e recomendações baseados na análise do DRE, permitindo melhor controle financeiro e planejamento estratégico.', 'todo', 'media', '2025-12-27 16:09:08', NULL, 0, NULL, '2025-12-30 00:00:00'),
(191, 'Mapear processos operacionais atuais', '**O que é:** Levantamento detalhado dos processos internos para identificar gargalos e oportunidades de automação.\n\n**Passo a Passo:**\n1. Reunir equipe operacional para levantamento.\n2. Documentar fluxos de atividades.\n3. Validar mapeamento com stakeholders.\n\n**Resultado Esperado:** Fluxograma completo dos processos operacionais atuais até 2026-01-10.', 'todo', 'alta', '2025-12-27 16:43:11', NULL, 0, 33, '2026-01-10 00:00:00'),
(192, 'Selecionar ferramenta de automação compatível', '**O que é:** Pesquisa e avaliação de plataformas tecnológicas para automação e integração dos processos.\n\n**Passo a Passo:**\n1. Definir critérios técnicos e financeiros.\n2. Fazer benchmark de ferramentas.\n3. Apresentar relatório para decisão da diretoria.\n\n**Resultado Esperado:** Relatório com recomendação de ferramenta até 2026-01-20.', 'todo', 'alta', '2025-12-27 16:43:11', NULL, 0, 33, '2026-01-20 00:00:00'),
(193, 'Configurar e implementar automações iniciais', '**O que é:** Configuração da plataforma escolhida para automatizar os processos mais críticos.\n\n**Passo a Passo:**\n1. Treinamento da equipe técnica.\n2. Desenvolvimento das automações.\n3. Testes e ajustes.\n\n**Resultado Esperado:** Processos piloto automatizados até 2026-02-15.', 'todo', 'alta', '2025-12-27 16:43:11', NULL, 0, 33, '2026-02-15 00:00:00'),
(194, 'Treinar equipe operacional nas novas ferramentas', '**O que é:** Capacitação da equipe para utilização eficiente dos sistemas de automação.\n\n**Passo a Passo:**\n1. Criar material didático e tutoriais.\n2. Realizar workshops e sessões práticas.\n3. Avaliar compreensão dos usuários.\n\n**Resultado Esperado:** Treinamento concluído com 90% de satisfação até 2026-02-28.', 'todo', 'alta', '2025-12-27 16:43:11', NULL, 0, 33, '2026-02-28 00:00:00'),
(195, 'Monitorar indicadores operacionais pós-implementação', '**O que é:** Acompanhar os KPIs para avaliar a eficácia das automações implantadas.\n\n**Passo a Passo:**\n1. Definir KPIs relevantes.\n2. Coletar dados contínuos.\n3. Realizar reuniões mensais para análise.\n\n**Resultado Esperado:** Relatórios mensais com melhorias e recomendações até 2026-03-31.', 'todo', 'alta', '2025-12-27 16:43:11', NULL, 0, 33, '2026-03-31 00:00:00'),
(196, 'Expandir automação para demais processos críticos', '**O que é:** Aplicar aprendizados e ampliar a automação para outras áreas operacionais.\n\n**Passo a Passo:**\n1. Priorizar processos adicionais.\n2. Desenvolver automações.\n3. Realizar treinamentos contínuos.\n\n**Resultado Esperado:** 80% dos processos manuais automatizados até 2026-06-30.', 'todo', 'alta', '2025-12-27 16:43:11', NULL, 0, 33, '2026-06-30 00:00:00'),
(197, 'Documentar processos atualizados e treinamentos', '**O que é:** Produção de manual interno atualizado com os novos processos e guias para equipes.\n\n**Passo a Passo:**\n1. Registrar procedimentos pós-automação.\n2. Criar documentos e vídeos explicativos.\n3. Disponibilizar em plataforma acessível.\n\n**Resultado Esperado:** Material disponível para toda a equipe até 2026-04-15.', 'todo', 'alta', '2025-12-27 16:43:11', NULL, 0, 33, '2026-04-15 00:00:00'),
(198, 'Estabelecer rotina de revisão contínua dos processos', '**O que é:** Implantar ciclos de melhoria contínua para manter a operação otimizada.\n\n**Passo a Passo:**\n1. Criar comitê de processos.\n2. Programar revisões periódicas.\n3. Implementar feedback das equipes.\n\n**Resultado Esperado:** Plano de revisão aprovado e em execução até 2026-05-15.', 'todo', 'alta', '2025-12-27 16:43:11', NULL, 0, 33, '2026-05-15 00:00:00'),
(199, 'Comunicar avanços para toda a empresa', '**O que é:** Garantir transparência e engajamento comunicando os resultados das automações.\n\n**Passo a Passo:**\n1. Criar newsletters internas.\n2. Realizar reuniões gerais de alinhamento.\n3. Recolher feedbacks dos colaboradores.\n\n**Resultado Esperado:** Comunicação eficiente com mais de 85% de engajamento até 2026-02-28.', 'todo', 'alta', '2025-12-27 16:43:11', NULL, 0, 33, '2026-02-28 00:00:00'),
(200, 'Mensurar impacto financeiro da automação', '**O que é:** Avaliar o retorno financeiro e ganhos de produtividade gerados pelo projeto.\n\n**Passo a Passo:**\n1. Levantar custos e investimentos.\n2. Quantificar ganhos em tempo e qualidade.\n3. Apresentar relatório para diretoria.\n\n**Resultado Esperado:** Relatório consolidado com ROI até 2026-07-31.', 'todo', 'alta', '2025-12-27 16:43:11', NULL, 0, 33, '2026-07-31 00:00:00'),
(201, 'Reunião Inicial com Stakeholders', 'Alinhar expectativas, objetivos e requisitos do novo site com os principais envolvidos da clínica', 'todo', 'alta', '2025-12-27 17:03:21', NULL, 0, 36, NULL),
(202, 'Pesquisa e Benchmarking', 'Analisar sites concorrentes e referências para definir melhores práticas e funcionalidades essenciais', 'todo', 'media', '2025-12-27 17:03:21', NULL, 0, 36, NULL),
(203, 'Definição de Requisitos Funcionais e Não Funcionais', 'Documentar todas as funcionalidades desejadas para o site e critérios de performance e segurança', 'todo', 'alta', '2025-12-27 17:03:21', NULL, 0, 36, NULL),
(204, 'Contratação/Seleção da Equipe Técnica', 'Selecionar equipe de desenvolvimento e design para o projeto do site', 'todo', 'media', '2025-12-27 17:03:21', NULL, 0, 36, NULL),
(205, 'Realizar análise detalhada de mercado', 'Coletar dados sobre potenciais regiões e segmentos para expansão', 'todo', 'alta', '2025-12-27 17:31:52', NULL, 0, 37, NULL),
(206, 'Desenvolver plano de entrada regional', 'Definir estratégias comerciais e canais para cada nova região', 'todo', 'alta', '2025-12-27 17:31:52', NULL, 0, 37, NULL),
(207, 'Mapear e prospectar potenciais parceiros estratégicos', 'Identificar e iniciar contato com empresas parceiras em potencial', 'todo', 'media', '2025-12-27 17:31:52', NULL, 0, 37, NULL),
(208, 'Planejar treinamentos e capacitação da equipe comercial', 'Organizar cronograma e conteúdo para qualificação da equipe', 'todo', 'media', '2025-12-27 17:31:52', NULL, 0, 37, NULL),
(209, 'Implementar sistema de monitoramento de indicadores de vendas', 'Configurar ferramentas para acompanhamento contínuo dos resultados', 'todo', 'alta', '2025-12-27 17:31:52', NULL, 0, 37, NULL),
(210, '[OBJ 1] Realizar pesquisa e análise de mercado', 'Coletar dados e avaliar 5 potenciais novos mercados para expansão comercial.', 'todo', 'alta', '2025-12-27 17:35:09', NULL, 0, 38, NULL),
(211, '[OBJ 1] Desenvolver plano de entrada para mercados selecionados', 'Criar estratégia detalhada para penetração e estabelecimento em 3 mercados prioritários.', 'todo', 'alta', '2025-12-27 17:35:09', NULL, 0, 38, NULL),
(212, '[OBJ 1] Lançar operações nos novos mercados', 'Implementar operações comerciais iniciais e iniciar vendas nos mercados escolhidos.', 'todo', 'alta', '2025-12-27 17:35:09', NULL, 0, 38, NULL),
(213, '[OBJ 1] Monitorar e analisar desempenho comercial dos novos mercados', 'Acompanhar resultados e ajustar estratégias até o final do ano.', 'todo', 'media', '2025-12-27 17:35:09', NULL, 0, 38, NULL),
(214, '[OBJ 2] Recrutar equipe de vendas especializada', 'Selecionar e contratar 15 profissionais para atuar nos novos mercados e canais.', 'todo', 'alta', '2025-12-27 17:35:09', NULL, 0, 38, NULL),
(215, '[OBJ 2] Realizar treinamentos para equipe comercial', 'Preparar vendedores para abordagem e conhecimento dos novos mercados e produtos.', 'todo', 'media', '2025-12-27 17:35:09', NULL, 0, 38, NULL),
(216, '[OBJ 2] Identificar e implementar novos canais de distribuição', 'Pesquisar e fechar parcerias comerciais para 2 novos canais de venda.', 'todo', 'alta', '2025-12-27 17:35:09', NULL, 0, 38, NULL),
(217, '[OBJ 2] Conduzir pesquisa de satisfação com parceiros de canal', 'Aplicar pesquisa anual para medir satisfação e identificar melhorias.', 'todo', 'media', '2025-12-27 17:35:09', NULL, 0, 38, NULL),
(218, '[OBJ 3] Mapear processos comerciais e identificar gargalos', 'Analisar ciclo de vendas atual para definir oportunidades de otimização.', 'todo', 'media', '2025-12-27 17:35:09', NULL, 0, 38, NULL),
(219, '[OBJ 3] Automatizar processos-chave do ciclo comercial', 'Implementar sistemas e ferramentas que automatizem 3 processos críticos.', 'todo', 'alta', '2025-12-27 17:35:09', NULL, 0, 38, NULL),
(220, '[OBJ 3] Monitorar tempos de atendimento e implementar melhorias', 'Avaliar e reduzir tempo médio de atendimento ao cliente em 15%.', 'todo', 'media', '2025-12-27 17:35:09', NULL, 0, 38, NULL),
(221, '[OBJ 1] Mapear processo comercial atual', 'Coletar informações e documentar todas as etapas do processo comercial que a clínica utiliza atualmente.', 'todo', 'alta', '2025-12-27 17:40:27', NULL, 0, 39, NULL),
(222, '[OBJ 1] Analisar e identificar gaps e melhorias', 'Realizar análise crítica do processo atual para identificar falhas e oportunidades de otimização.', 'todo', 'alta', '2025-12-27 17:40:27', NULL, 0, 39, NULL),
(223, '[OBJ 1] Criar documentação do novo fluxo comercial', 'Desenvolver documentação detalhada com etapas, responsáveis e padrões do processo comercial estruturado.', 'todo', 'media', '2025-12-27 17:40:27', NULL, 0, 39, NULL),
(224, '[OBJ 1] Validar novo fluxo com equipe', 'Apresentar o novo processo para a equipe comercial e ajustá-lo conforme feedbacks recebidos.', 'todo', 'media', '2025-12-27 17:40:27', NULL, 0, 39, NULL),
(225, '[OBJ 2] Selecionar e implementar ferramenta de CRM', 'Escolher e configurar sistema que suporte o processo comercial e permita controle e análise de dados.', 'todo', 'alta', '2025-12-27 17:40:27', NULL, 0, 39, NULL),
(226, '[OBJ 2] Elaborar plano de treinamento para equipe comercial', 'Desenvolver conteúdo e cronograma para capacitar equipe nas novidades do processo e uso da ferramenta.', 'todo', 'media', '2025-12-27 17:40:27', NULL, 0, 39, NULL),
(227, '[OBJ 2] Realizar treinamentos presenciais ou online', 'Executar os treinamentos previstos e garantir a absorção dos conceitos por toda a equipe.', 'todo', 'alta', '2025-12-27 17:40:27', NULL, 0, 39, NULL),
(228, '[OBJ 2] Monitorar indicadores comerciais pós-implementação', 'Acompanhar resultados comerciais para avaliar eficácia do novo processo e realizar ajustes, se necessário.', 'todo', 'media', '2025-12-27 17:40:27', NULL, 0, 39, NULL);

